function createGravityWalk() {
    const controls = Object.freeze([
        rangeControl("sides", "Sides", 3, 12, 1, GRAVITY_DEFAULTS.sides),
        rangeControl("roundness", "Roundness", 0, 1, 0.01, GRAVITY_DEFAULTS.roundness, (v) => Number(v).toFixed(2)),
        rangeControl("rotation", "Shape angle", -180, 180, 1, GRAVITY_DEFAULTS.rotation, (v) => `${Math.round(v)}°`),
        rangeControl("gravity", "Gravity", 0, 3, 0.01, GRAVITY_DEFAULTS.gravity, (v) => Number(v).toFixed(2)),
        rangeControl("gravityAngle", "Gravity angle", -180, 180, 1, GRAVITY_DEFAULTS.gravityAngle, (v) => `${Math.round(v)}°`),
        rangeControl("drag", "Drag", 0, 1.5, 0.01, GRAVITY_DEFAULTS.drag, (v) => Number(v).toFixed(2)),
        rangeControl("kick", "Kick strength", 0.1, 3, 0.05, GRAVITY_DEFAULTS.kick, (v) => Number(v).toFixed(2)),
    ]);
    const state = { ...GRAVITY_DEFAULTS };
    const events = makeEventQueue();
    const samplesPerSide = 18;
    let path = measurePolyline(morphedPolygon(state.sides, state.roundness, state.rotation), true);
    let pathBounds = pointBounds(path.points);
    let beadDistance = 0;
    let beadVelocity = 0;
    let cornerGlow = 0;
    let lastSector = 0;
    let dragging = false;
    let dragDistance = 0;
    let dragVelocity = 0;
    let dragTime = 0;
    let trail = [];
    let trailClock = 0;
    const gravityDirection = () => {
        const angle = radians(state.gravityAngle);
        return { x: Math.sin(angle), y: -Math.cos(angle) };
    };
    const bead = () => pointAtDistance(path, beadDistance);
    const height = (point) => -dot(point, gravityDirection());
    const heightRange = () => {
        let minimum = Infinity;
        let maximum = -Infinity;
        for (const point of path.points) {
            const value = height(point);
            minimum = Math.min(minimum, value);
            maximum = Math.max(maximum, value);
        }
        return { minimum, maximum, span: Math.max(EPSILON, maximum - minimum) };
    };
    const height01 = (point) => {
        const range = heightRange();
        return clamp((height(point) - range.minimum) / range.span);
    };
    const speedReference = () => Math.max(0.25, Math.sqrt(2 * Math.max(0.05, state.gravity) * heightRange().span));
    const accelerationAt = (requestedDistance) => {
        const sample = pointAtDistance(path, requestedDistance);
        return state.gravity * dot(gravityDirection(), sample.tangent);
    };
    function placeAtHighPoint() {
        let bestIndex = 0;
        let bestHeight = -Infinity;
        path.points.forEach((point, index) => {
            const candidate = height(point);
            if (candidate > bestHeight) {
                bestHeight = candidate;
                bestIndex = index;
            }
        });
        beadDistance = wrap(path.cumulative[bestIndex] + path.total * 0.009, path.total);
        beadVelocity = 0;
        lastSector = Math.floor(pointAtDistance(path, beadDistance).edgeIndex / samplesPerSide);
        trail = [bead()];
    }
    function rebuildPath(preserve = true) {
        const oldPoint = path?.edges?.length ? bead() : null;
        const oldVelocity = oldPoint ? scale(oldPoint.tangent, beadVelocity) : null;
        path = measurePolyline(morphedPolygon(Math.round(state.sides), state.roundness, state.rotation, 0.72, samplesPerSide), true);
        pathBounds = pointBounds(path.points);
        if (preserve && oldPoint) {
            const nearest = closestPointOnPolyline(oldPoint, path);
            beadDistance = nearest?.pathDistance ?? 0;
            beadVelocity = oldVelocity ? dot(oldVelocity, nearest?.tangent ?? { x: 1, y: 0 }) : 0;
            lastSector = Math.floor((nearest?.edgeIndex ?? 0) / samplesPerSide);
            trail = [bead()];
        }
        else {
            placeAtHighPoint();
        }
    }
    function reset() {
        Object.assign(state, GRAVITY_DEFAULTS);
        events.clear();
        cornerGlow = 0;
        dragging = false;
        dragVelocity = 0;
        dragTime = 0;
        trailClock = 0;
        rebuildPath(false);
    }
    function setParam(key, value) {
        const next = coerceControl(controls, key, value);
        if (next === undefined)
            return;
        state[key] = next;
        if (["sides", "roundness", "rotation"].includes(key))
            rebuildPath(true);
    }
    function step(dt) {
        const h = finiteStep(dt);
        if (h <= 0)
            return;
        cornerGlow *= Math.exp(-h / 0.11);
        if (dragging || path.total <= EPSILON)
            return;
        const oldSample = bead();
        const halfVelocity = beadVelocity + 0.5 * accelerationAt(beadDistance) * h;
        beadDistance = wrap(beadDistance + halfVelocity * h, path.total);
        beadVelocity = halfVelocity + 0.5 * accelerationAt(beadDistance) * h;
        beadVelocity *= Math.exp(-state.drag * h);
        beadVelocity = clamp(beadVelocity, -5, 5);
        const current = bead();
        const sector = Math.floor(current.edgeIndex / samplesPerSide);
        if (sector !== lastSector) {
            const speed01 = clamp(Math.abs(beadVelocity) / speedReference());
            const sharpness = 1 - state.roundness;
            cornerGlow = Math.max(cornerGlow, sharpness * (0.25 + 0.75 * speed01));
            if (sharpness > 0.01) {
                events.push(transient(`corner-${sector}`, height01(current), sharpness * (0.18 + 0.62 * speed01), clamp(current.x / 0.72, -1, 1), "triangle", { decaySeconds: 0.1 + 0.1 * sharpness, attackNoise: 0.08 * speed01 * sharpness }));
            }
            lastSector = sector;
        }
        trailClock += h;
        if (trailClock >= 1 / 60 || distance(oldSample, current) > 0.025) {
            trailClock = 0;
            trail.push({ x: current.x, y: current.y });
            if (trail.length > 52)
                trail.shift();
        }
    }
    function draw(painter) {
        const current = bead();
        trail.forEach((point, index) => {
            const amount = (index + 1) / Math.max(1, trail.length);
            painter.circle(point, 0.005 + 0.009 * amount, {
                color: PHYSICS_COLORS.brass,
                fill: PHYSICS_COLORS.brass,
                width: 0,
                alpha: 0.04 + 0.22 * amount * amount,
            });
        });
        painter.polyline(path.points, {
            close: true,
            color: PHYSICS_COLORS.brass,
            width: 1.6,
            fill: "rgba(232,196,107,0.025)",
        });
        for (let side = 0; side < state.sides; side += 1) {
            painter.circle(path.points[side * samplesPerSide], 0.009, {
                color: PHYSICS_COLORS.brass,
                fill: PHYSICS_COLORS.background,
                width: 1,
                alpha: 0.52 * (1 - state.roundness) + 0.12,
            });
        }
        const direction = gravityDirection();
        const arrowStart = { x: 0.72, y: 0.68 };
        const arrowEnd = add(arrowStart, scale(direction, 0.22));
        painter.arrow(arrowStart, arrowEnd, { color: PHYSICS_COLORS.muted, width: 1.1, alpha: 0.85 });
        painter.text("g", add(arrowEnd, scale(direction, 0.05)), { color: PHYSICS_COLORS.muted, size: 9 });
        painter.circle(current, 0.025 + 0.012 * cornerGlow, {
            color: PHYSICS_COLORS.point,
            fill: PHYSICS_COLORS.brass,
            width: 1.4,
        });
        const velocityTip = add(current, scale(current.tangent, clamp(beadVelocity * 0.075, -0.22, 0.22)));
        if (Math.abs(beadVelocity) > 0.04) {
            painter.arrow(current, velocityTip, { color: PHYSICS_COLORS.point, width: 1, alpha: 0.68, headLength: 0.028 });
        }
    }
    function voices() {
        const current = bead();
        const potential = height01(current);
        const speed01 = clamp(Math.abs(beadVelocity) / speedReference());
        const kinetic = clamp((beadVelocity * beadVelocity) / (speedReference() ** 2));
        const pan = clamp((current.x - pathBounds.minX) / Math.max(EPSILON, pathBounds.maxX - pathBounds.minX) * 2 - 1, -1, 1);
        return [
            normalizedVoice({
                key: "potential",
                pitch01: potential,
                gain: 0.09 + 0.23 * Math.sqrt(speed01) + 0.16 * cornerGlow,
                pan,
                waveform: "sine",
            }),
            normalizedVoice({
                key: "kinetic",
                pitch01: kinetic,
                gain: 0.02 + 0.22 * Math.sqrt(kinetic),
                pan: clamp(pan * 0.72, -1, 1),
                waveform: "triangle",
            }),
        ];
    }
    function metrics() {
        const current = bead();
        const kinetic = clamp((beadVelocity * beadVelocity) / (speedReference() ** 2));
        return [
            ["State", dragging ? "held" : Math.abs(beadVelocity) < 0.018 ? "resting" : "moving"],
            ["Speed", roundTo(Math.abs(beadVelocity))],
            ["Potential", `${Math.round(height01(current) * 100)}%`],
            ["Kinetic", `${Math.round(kinetic * 100)}%`],
        ];
    }
    function pointerDown(point) {
        const nearest = closestPointOnPolyline(point, path);
        if (!nearest || nearest.distance > 0.18)
            return;
        dragging = true;
        beadDistance = nearest.pathDistance;
        beadVelocity = 0;
        dragVelocity = 0;
        dragDistance = beadDistance;
        dragTime = Number(point.time) || 0;
        trail = [bead()];
    }
    function pointerMove(point) {
        if (!dragging)
            return;
        const nearest = closestPointOnPolyline(point, path);
        if (!nearest)
            return;
        const now = Number(point.time) || dragTime + 1 / 60;
        const elapsed = clamp(now - dragTime, 1 / 240, 0.1);
        const instantaneous = cyclicDelta(nearest.pathDistance, dragDistance, path.total) / elapsed;
        dragVelocity = lerp(dragVelocity, clamp(instantaneous, -5, 5), 0.38);
        dragDistance = nearest.pathDistance;
        dragTime = now;
        beadDistance = nearest.pathDistance;
        lastSector = Math.floor(nearest.edgeIndex / samplesPerSide);
    }
    function pointerUp(point) {
        if (!dragging)
            return;
        pointerMove(point);
        dragging = false;
        beadVelocity = dragVelocity;
    }
    function primaryAction() {
        const direction = beadVelocity < -0.02 ? -1 : 1;
        beadVelocity += direction * state.kick;
        const current = bead();
        events.push(transient("kick", height01(current), 0.52, clamp(current.x / 0.72, -1, 1), "triangle", {
            attackSeconds: 0.002,
            decaySeconds: 0.18,
            attackNoise: 0.1,
        }));
    }
    reset();
    return {
        id: "gravity-walk",
        title: "Gravity Walk",
        kicker: "Physics · 01 · Contour-constrained dynamics",
        description: "A point falls around a closed contour. Shape becomes an energy landscape.",
        instruction: "Drag the bead around the contour and release it, or use Kick to add tangent velocity.",
        lesson: "Gravity is projected onto the contour tangent, exchanging potential and kinetic energy until drag selects a stable low point.",
        color: PHYSICS_COLORS.brass,
        mappings: [["Height", "pitch"], ["Speed", "kinetic voice level"], ["Corner crossing", "accent"], ["Horizontal position", "stereo"]],
        controls,
        state,
        reset,
        setParam,
        step,
        draw,
        voices,
        consumeEvents: () => events.drain(),
        metrics,
        pointerDown,
        pointerMove,
        pointerUp,
        primaryActionLabel: "Kick",
        primaryAction,
    };
}

function createRicochet() {
    const controls = Object.freeze([
        selectControl("preset", "Arena preset", RICOCHET_PRESETS, RICOCHET_DEFAULTS.preset),
        rangeControl("sides", "Sides / star tips", 3, 12, 1, RICOCHET_DEFAULTS.sides),
        rangeControl("rotation", "Arena angle", -180, 180, 1, RICOCHET_DEFAULTS.rotation, (v) => `${Math.round(v)}°`),
        rangeControl("rotationSpeed", "Rotation speed", -120, 120, 1, RICOCHET_DEFAULTS.rotationSpeed, (v) => `${Math.round(v)}°/s`),
        rangeControl("launchVelocity", "Launch velocity", 0.15, 4, 0.01, RICOCHET_DEFAULTS.launchVelocity, (v) => Number(v).toFixed(2)),
        rangeControl("launchAngle", "Launch angle", -180, 180, 1, RICOCHET_DEFAULTS.launchAngle, (v) => `${Math.round(v)}°`),
        rangeControl("restitution", "Reflection", 0.55, 1, 0.01, RICOCHET_DEFAULTS.restitution, (v) => Number(v).toFixed(2)),
        rangeControl("trail", "Trail", 24, 240, 1, RICOCHET_DEFAULTS.trail),
    ]);
    const state = { ...RICOCHET_DEFAULTS };
    const events = makeEventQueue();
    const ballRadius = 0.025;
    const maximumBalls = 12;
    let localPolygon = [];
    let arenaAngle = 0;
    let balls = [];
    let nextBallId = 1;
    let collisionCount = 0;
    let lastEdge = -1;
    let lastIncidence = 0;
    let impactGlow = 0;
    let lastImpact = null;
    let interaction = null;
    let geometryEdited = false;
    const worldPolygon = () => localPolygon.map((point) => rotate(point, arenaAngle));
    function arenaWalls(points = worldPolygon()) {
        const orientation = polygonSignedArea(points) < 0 ? -1 : 1;
        return polygonEdges(points).map((edge) => {
            const tangent = normalize(sub(edge.b, edge.a));
            return {
                ...edge,
                tangent,
                length: distance(edge.a, edge.b),
                inward: scale(perpendicular(tangent), orientation),
            };
        });
    }
    function nearestBoundary(point, walls) {
        let best = null;
        for (const wall of walls) {
            const candidate = closestPointOnSegment(point, wall.a, wall.b);
            if (!best || candidate.distance < best.distance)
                best = { ...candidate, wall };
        }
        return best;
    }
    function isSafePosition(point, points = worldPolygon(), walls = arenaWalls(points), margin = ballRadius) {
        if (!pointInPolygon(point, points))
            return false;
        const nearest = nearestBoundary(point, walls);
        return Boolean(nearest && nearest.distance >= margin - 1e-6);
    }
    function safeSpawnPoint(preferred = null) {
        const points = worldPolygon();
        const walls = arenaWalls(points);
        const candidates = [];
        if (preferred)
            candidates.push(preferred);
        candidates.push(state.preset === "tunnel" ? { x: -0.53, y: 0.02 } : { x: -0.18, y: 0.08 }, { x: 0, y: 0 });
        for (let row = 0; row < 13; row += 1) {
            for (let column = 0; column < 15; column += 1) {
                candidates.push({ x: -0.7 + column * 0.1, y: -0.6 + row * 0.1 });
            }
        }
        return candidates.find((candidate) => (isSafePosition(candidate, points, walls, ballRadius * 1.35)
            && balls.every((ball) => distance(candidate, ball.position) > ballRadius * 2.6))) ?? candidates.find((candidate) => isSafePosition(candidate, points, walls, ballRadius * 1.1))
            ?? { x: 0, y: -0.42 };
    }
    function makeBall(position, angle, speed) {
        const direction = { x: Math.cos(angle), y: Math.sin(angle) };
        return {
            id: nextBallId++,
            position: { ...position },
            velocity: scale(direction, speed),
            trail: [{ ...position }],
            trailClock: 0,
            impactGlow: 0,
            aiming: false,
        };
    }
    function spawnBall({ position = null, angle = null, speed = null, emit = true } = {}) {
        if (balls.length >= maximumBalls)
            return null;
        const spawnIndex = balls.length;
        const launchAngle = angle ?? radians(state.launchAngle + spawnIndex * 17);
        const launchSpeed = speed ?? state.launchVelocity;
        const ball = makeBall(safeSpawnPoint(position), launchAngle, launchSpeed);
        balls.push(ball);
        if (emit) {
            events.push(transient(`launch-${ball.id}`, clamp((ball.position.y + 0.8) / 1.6), 0.18 + 0.12 * clamp(launchSpeed / 4), clamp(ball.position.x / 0.8, -1, 1), "sine", { decaySeconds: 0.08 }));
        }
        return ball;
    }
    function resetDynamics() {
        balls = [];
        nextBallId = 1;
        collisionCount = 0;
        lastEdge = -1;
        lastIncidence = 0;
        impactGlow = 0;
        lastImpact = null;
        interaction = null;
        events.clear();
        spawnBall({ position: { x: -0.18, y: 0.08 }, angle: radians(state.launchAngle), emit: false });
    }
    function orientArena(points) {
        return polygonSignedArea(points) < 0 ? [...points].reverse() : points;
    }
    function rebuildArena(preserveDynamics = true) {
        localPolygon = orientArena(ricochetPresetPoints(state.preset, state.sides));
        geometryEdited = false;
        if (!preserveDynamics) {
            resetDynamics();
            return;
        }
        repairBallsAfterEdit();
    }
    function reset() {
        Object.assign(state, RICOCHET_DEFAULTS);
        arenaAngle = radians(state.rotation);
        rebuildArena(false);
    }
    function setParam(key, value) {
        const next = coerceControl(controls, key, value);
        if (next === undefined)
            return;
        state[key] = next;
        if (key === "preset" || key === "sides")
            rebuildArena(true);
        else if (key === "rotation") {
            arenaAngle = radians(state.rotation);
            repairBallsAfterEdit();
        }
        else if (key === "launchVelocity" && balls.length === 1 && collisionCount === 0) {
            const ball = balls[0];
            if (!ball.aiming && length(ball.velocity) > EPSILON) {
                ball.velocity = scale(normalize(ball.velocity), state.launchVelocity);
            }
        }
    }
    function wallVelocityAt(point, angularVelocity) {
        return scale(perpendicular(point), angularVelocity);
    }
    function registerImpact(ball, point, normal, wall, incomingVelocity, angularVelocity) {
        const wallVelocity = wallVelocityAt(point, angularVelocity);
        const relativeVelocity = sub(incomingVelocity, wallVelocity);
        const impactSpeed = length(relativeVelocity);
        const approach = clamp(-dot(normalize(relativeVelocity), normal));
        lastIncidence = Math.acos(approach) * 180 / Math.PI;
        lastEdge = wall.index;
        lastImpact = { point: { ...point }, normal: { ...normal }, ballId: ball.id };
        const energy = clamp(impactSpeed / 3.2);
        impactGlow = Math.max(impactGlow, 0.25 + 0.75 * energy);
        ball.impactGlow = Math.max(ball.impactGlow, 0.3 + 0.7 * energy);
        collisionCount += 1;
        events.push(transient(`tine-${wall.index}`, clamp(lastIncidence / 90), 0.08 + 0.82 * energy, clamp(point.x / 0.8, -1, 1), "triangle", {
            decaySeconds: clamp(0.055 + 0.16 * wall.length / 0.8, 0.065, 0.3),
            attackNoise: 0.035 + 0.055 * energy,
        }));
    }
    function reflectBall(ball, contact, normal, angularVelocity) {
        const wallVelocity = wallVelocityAt(contact.point, angularVelocity);
        const relative = sub(ball.velocity, wallVelocity);
        const normalSpeed = dot(relative, normal);
        if (normalSpeed >= -1e-7)
            return false;
        const incoming = { ...ball.velocity };
        const reflected = sub(relative, scale(normal, (1 + state.restitution) * normalSpeed));
        ball.velocity = clampMagnitude(add(wallVelocity, reflected), 6);
        registerImpact(ball, contact.point, normal, contact.wall, incoming, angularVelocity);
        return true;
    }
    function inwardContactNormal(contact, safePoint, points) {
        let normal = normalize(sub(safePoint, contact.point), contact.wall.inward);
        if (dot(normal, contact.wall.inward) < 0.1)
            normal = contact.wall.inward;
        if (!pointInPolygon(add(contact.point, scale(normal, ballRadius * 1.2)), points)) {
            normal = contact.wall.inward;
        }
        return normal;
    }
    function relocateBall(ball, preferred = ball.position) {
        const position = safeSpawnPoint(preferred);
        ball.position = { ...position };
        ball.trail = [{ ...position }];
        ball.trailClock = 0;
    }
    function containBall(ball, points, walls, angularVelocity, soundContact = true) {
        if (isSafePosition(ball.position, points, walls))
            return true;
        const contact = nearestBoundary(ball.position, walls);
        if (!contact) {
            relocateBall(ball);
            return false;
        }
        const wasInside = pointInPolygon(ball.position, points);
        const normal = wasInside
            ? inwardContactNormal(contact, ball.position, points)
            : contact.wall.inward;
        const corrected = add(contact.point, scale(normal, ballRadius + 2e-5));
        if (!isSafePosition(corrected, points, walls, ballRadius * 0.98)) {
            relocateBall(ball);
            return false;
        }
        if (soundContact)
            reflectBall(ball, contact, normal, angularVelocity);
        ball.position = corrected;
        return true;
    }
    function integrateBall(ball, dt, points, walls, angularVelocity) {
        if (ball.aiming || length(ball.velocity) <= EPSILON) {
            containBall(ball, points, walls, angularVelocity, false);
            return;
        }
        if (!containBall(ball, points, walls, angularVelocity, true))
            return;
        let remaining = dt;
        let contacts = 0;
        while (remaining > 1e-8 && contacts < 5) {
            const start = { ...ball.position };
            const target = add(start, scale(ball.velocity, remaining));
            if (isSafePosition(target, points, walls)) {
                ball.position = target;
                remaining = 0;
                break;
            }
            let safeAmount = 0;
            let unsafeAmount = 1;
            for (let iteration = 0; iteration < 15; iteration += 1) {
                const amount = (safeAmount + unsafeAmount) / 2;
                const candidate = add(start, scale(ball.velocity, remaining * amount));
                if (isSafePosition(candidate, points, walls))
                    safeAmount = amount;
                else
                    unsafeAmount = amount;
            }
            const safePoint = add(start, scale(ball.velocity, remaining * safeAmount));
            const unsafePoint = add(start, scale(ball.velocity, remaining * unsafeAmount));
            const contact = nearestBoundary(unsafePoint, walls);
            if (!contact) {
                relocateBall(ball, start);
                return;
            }
            const normal = inwardContactNormal(contact, safePoint, points);
            ball.position = add(contact.point, scale(normal, ballRadius + 2e-5));
            if (!isSafePosition(ball.position, points, walls, ballRadius * 0.98)) {
                ball.position = safePoint;
            }
            const reflected = reflectBall(ball, contact, normal, angularVelocity);
            remaining *= 1 - safeAmount;
            contacts += 1;
            if (!reflected || safeAmount < 1e-5)
                remaining *= 0.5;
        }
        if (contacts >= 5 && remaining > 0)
            ball.velocity = scale(ball.velocity, 0.985);
        containBall(ball, points, walls, angularVelocity, false);
    }
    function repairBallsAfterEdit() {
        const points = worldPolygon();
        const walls = arenaWalls(points);
        for (const ball of balls) {
            if (!isSafePosition(ball.position, points, walls))
                relocateBall(ball);
        }
    }
    function step(dt) {
        const h = finiteStep(dt);
        if (h <= 0)
            return;
        impactGlow *= Math.exp(-h / 0.1);
        for (const ball of balls)
            ball.impactGlow *= Math.exp(-h / 0.085);
        const angularVelocity = radians(state.rotationSpeed);
        const fastest = balls.reduce((maximum, ball) => Math.max(maximum, length(ball.velocity)), 0);
        const projectedTravel = (fastest + Math.abs(angularVelocity) * 0.9) * h;
        const substeps = Math.max(1, Math.min(12, Math.ceil(projectedTravel / (ballRadius * 0.42))));
        const substep = h / substeps;
        for (let index = 0; index < substeps; index += 1) {
            arenaAngle = wrap(arenaAngle + angularVelocity * substep + Math.PI, TAU) - Math.PI;
            const points = worldPolygon();
            const walls = arenaWalls(points);
            for (const ball of balls)
                integrateBall(ball, substep, points, walls, angularVelocity);
        }
        for (const ball of balls) {
            ball.trailClock += h;
            if (ball.trailClock >= 1 / 90) {
                ball.trailClock = 0;
                ball.trail.push({ ...ball.position });
                while (ball.trail.length > state.trail)
                    ball.trail.shift();
            }
        }
    }
    function draw(painter) {
        const polygon = worldPolygon();
        const currentWalls = arenaWalls(polygon);
        for (const ball of balls) {
            ball.trail.forEach((point, index) => {
                const amount = (index + 1) / Math.max(1, ball.trail.length);
                painter.circle(point, 0.0025 + 0.0045 * amount, {
                    color: PHYSICS_COLORS.blue,
                    fill: PHYSICS_COLORS.blue,
                    width: 0,
                    alpha: 0.018 + 0.15 * amount * amount,
                });
            });
        }
        painter.polyline(polygon, {
            close: true,
            color: PHYSICS_COLORS.blue,
            width: 1.6,
            fill: "rgba(125,180,255,0.025)",
        });
        currentWalls.forEach((wall) => {
            const active = wall.index === lastEdge ? impactGlow : 0;
            painter.line(wall.a, wall.b, {
                color: active > 0.05 ? PHYSICS_COLORS.point : PHYSICS_COLORS.blue,
                width: 1.15 + 2.3 * active,
                alpha: 0.64 + 0.34 * active,
            });
            const midpoint = scale(add(wall.a, wall.b), 0.5);
            if (polygon.length <= 16) {
                painter.circle(midpoint, 0.013, {
                    color: PHYSICS_COLORS.muted,
                    fill: PHYSICS_COLORS.background,
                    width: 1,
                    alpha: 0.78,
                });
                painter.text("+", midpoint, { color: PHYSICS_COLORS.point, size: 8, alpha: 0.76 });
            }
            else {
                painter.circle(midpoint, 0.006, { color: PHYSICS_COLORS.faint, fill: PHYSICS_COLORS.background, width: 1, alpha: 0.42 });
            }
        });
        polygon.forEach((point, index) => {
            const active = interaction?.type === "vertex" && interaction.index === index;
            painter.circle(point, active ? 0.027 : 0.018, {
                color: active ? PHYSICS_COLORS.point : PHYSICS_COLORS.blue,
                fill: PHYSICS_COLORS.background,
                width: active ? 1.7 : 1.1,
                alpha: 0.9,
            });
        });
        if (lastImpact) {
            painter.arrow(lastImpact.point, add(lastImpact.point, scale(lastImpact.normal, 0.14)), {
                color: PHYSICS_COLORS.coral,
                width: 1,
                alpha: 0.25 + 0.65 * impactGlow,
                headLength: 0.026,
            });
        }
        if (interaction?.type === "aim") {
            const ball = balls.find((candidate) => candidate.id === interaction.ballId);
            if (ball) {
                painter.arrow(ball.position, interaction.aimPoint, {
                    color: PHYSICS_COLORS.point,
                    width: 1,
                    alpha: 0.78,
                    dash: [4, 4],
                    headLength: 0.035,
                });
            }
        }
        for (const ball of balls) {
            painter.circle(ball.position, ballRadius + 0.009 * ball.impactGlow, {
                color: PHYSICS_COLORS.point,
                fill: PHYSICS_COLORS.blue,
                width: 1.35,
            });
        }
    }
    function voices() {
        return balls.map((ball) => normalizedVoice({
            key: `flight-${ball.id}`,
            pitch01: clamp((ball.position.y + 0.8) / 1.6),
            gain: ball.aiming ? 0.012 : 0.018 + 0.016 * clamp(length(ball.velocity) / 4),
            pan: clamp(ball.position.x / 0.8, -1, 1),
            waveform: "sine",
        }));
    }
    function metrics() {
        const fastest = balls.reduce((maximum, ball) => Math.max(maximum, length(ball.velocity)), 0);
        return [
            ["Collisions", collisionCount],
            ["Balls", balls.length],
            ["Fastest", roundTo(fastest)],
            ["Incidence", lastEdge < 0 ? "—" : `${roundTo(lastIncidence, 1)}°`],
            ["Vertices", localPolygon.length],
            ["Arena", `${state.preset}${geometryEdited ? " · edited" : ""}`],
        ];
    }
    function pointerDown(point) {
        const polygon = worldPolygon();
        const currentWalls = arenaWalls(polygon);
        let nearestVertex = { index: -1, distance: Infinity };
        polygon.forEach((vertex, index) => {
            const candidateDistance = distance(point, vertex);
            if (candidateDistance < nearestVertex.distance)
                nearestVertex = { index, distance: candidateDistance };
        });
        if (nearestVertex.distance <= 0.065) {
            interaction = { type: "vertex", index: nearestVertex.index };
            return;
        }
        const edge = nearestBoundary(point, currentWalls);
        if (edge && edge.distance <= 0.045 && localPolygon.length < 32) {
            const localPoint = rotate(edge.point, -arenaAngle);
            const nextPolygon = [...localPolygon];
            nextPolygon.splice(edge.wall.index + 1, 0, localPoint);
            if (validRicochetPolygon(nextPolygon)) {
                localPolygon = nextPolygon;
                geometryEdited = true;
                interaction = { type: "vertex", index: edge.wall.index + 1 };
                repairBallsAfterEdit();
                return;
            }
        }
        if (!isSafePosition(point, polygon, currentWalls, ballRadius * 1.05))
            return;
        if (balls.some((ball) => distance(point, ball.position) < ballRadius * 2.8))
            return;
        const ball = spawnBall({ position: point, angle: 0, speed: 0, emit: false });
        if (!ball)
            return;
        ball.aiming = true;
        interaction = { type: "aim", ballId: ball.id, origin: { ...ball.position }, aimPoint: { ...point } };
    }
    function pointerMove(point) {
        if (interaction?.type === "aim") {
            interaction.aimPoint = { x: point.x, y: point.y };
            return;
        }
        if (interaction?.type !== "vertex")
            return;
        let localPoint = rotate(point, -arenaAngle);
        const radius = length(localPoint);
        if (radius > 0.92)
            localPoint = scale(localPoint, 0.92 / radius);
        const nextPolygon = localPolygon.map((vertex, index) => (index === interaction.index ? localPoint : vertex));
        if (!validRicochetPolygon(nextPolygon))
            return;
        localPolygon = nextPolygon;
        geometryEdited = true;
        repairBallsAfterEdit();
    }
    function pointerUp(point) {
        if (interaction?.type === "vertex") {
            pointerMove(point);
            interaction = null;
            return false;
        }
        if (interaction?.type !== "aim")
            return false;
        const ball = balls.find((candidate) => candidate.id === interaction.ballId);
        if (!ball) {
            interaction = null;
            return false;
        }
        const direction = normalize(sub(point, interaction.origin), {
            x: Math.cos(radians(state.launchAngle)),
            y: Math.sin(radians(state.launchAngle)),
        });
        const dragDistance = distance(point, interaction.origin);
        const velocityScale = clamp(dragDistance / 0.48, 0.18, 1);
        const launchVelocity = state.launchVelocity * velocityScale;
        ball.velocity = scale(direction, launchVelocity);
        ball.aiming = false;
        ball.trail = [{ ...ball.position }];
        state.launchAngle = Math.atan2(direction.y, direction.x) * 180 / Math.PI;
        events.push(transient(`launch-${ball.id}`, clamp((ball.position.y + 0.8) / 1.6), 0.25, clamp(ball.position.x / 0.8, -1, 1), "sine", {
            decaySeconds: 0.09,
        }));
        interaction = null;
        return true;
    }
    function primaryAction() {
        spawnBall();
    }
    reset();
    return {
        id: "ricochet",
        title: "Ricochet",
        kicker: "Physics · 02 · Polygonal billiards",
        description: "",
        instruction: "Drag a vertex to reshape the arena. Press an edge and drag to insert a vertex. Press empty space inside to spawn a ball, drag to aim, and release to launch.",
        lesson: "Each edge acts as a struck tine: incidence angle sets continuous pitch and relative impact velocity sets amplitude. Concave and rotating boundaries reveal focusing, rapid collision trains, and moving-wall energy exchange.",
        color: PHYSICS_COLORS.blue,
        mappings: [["Incidence angle", "tine pitch"], ["Impact velocity", "amplitude"], ["Edge length", "tine decay"], ["Impact x-position", "stereo"], ["Ball position", "faint flight voice"]],
        get controls() {
            return state.preset === "tunnel"
                ? controls.filter((control) => control.key !== "sides")
                : controls;
        },
        state,
        reset,
        setParam,
        step,
        draw,
        voices,
        consumeEvents: () => events.drain(),
        metrics,
        pointerDown,
        pointerMove,
        pointerUp,
        primaryActionLabel: "Spawn ball",
        primaryAction,
    };
}

function createRigidity() {
    const controls = Object.freeze([
        selectControl("structure", "Framework", [
            { value: "square", label: "Square" },
            { value: "braced", label: "Braced square" },
            { value: "triangle", label: "Triangle" },
            { value: "truss", label: "Two-bay truss" },
        ], RIGIDITY_DEFAULTS.structure),
        rangeControl("load", "Load", 0, 3, 0.01, RIGIDITY_DEFAULTS.load, (v) => Number(v).toFixed(2)),
        rangeControl("loadAngle", "Load angle", -45, 45, 1, RIGIDITY_DEFAULTS.loadAngle, (v) => `${Math.round(v)}°`),
        rangeControl("flexibility", "Joint flexibility", 0, 1, 0.01, RIGIDITY_DEFAULTS.flexibility, (v) => Number(v).toFixed(2)),
        rangeControl("damping", "Damping", 0, 5, 0.05, RIGIDITY_DEFAULTS.damping, (v) => Number(v).toFixed(2)),
    ]);
    const state = { ...RIGIDITY_DEFAULTS };
    const events = makeEventQueue();
    let nodes = [];
    let bars = [];
    let outline = [];
    let restArea = 1;
    let draggedNode = -1;
    let dragTarget = null;
    let maxError = 0;
    let peakForce = 0;
    function definition() {
        return STRUCTURES[state.structure] ?? STRUCTURES.square;
    }
    function resetDynamics() {
        const model = definition();
        const pins = new Set(model.pins);
        nodes = model.points.map(([x, y], id) => ({
            id,
            p: { x, y },
            rest: { x, y },
            v: { x: 0, y: 0 },
            pinned: pins.has(id),
            stress: 0,
        }));
        bars = model.bars.map(([a, b], id) => ({
            id,
            a,
            b,
            restLength: distance(nodes[a].p, nodes[b].p),
            lambda: 0,
            error: 0,
        }));
        outline = [...model.outline];
        restArea = Math.max(EPSILON, polygonArea(outline.map((id) => nodes[id].p)));
        draggedNode = -1;
        dragTarget = null;
        maxError = 0;
        peakForce = 0;
        events.clear();
    }
    function reset() {
        Object.assign(state, RIGIDITY_DEFAULTS);
        resetDynamics();
    }
    function setParam(key, value) {
        const next = coerceControl(controls, key, value);
        if (next === undefined)
            return;
        state[key] = next;
        if (key === "structure")
            resetDynamics();
    }
    function inverseMass(node) {
        return node.pinned || node.id === draggedNode ? 0 : 1;
    }
    function step(dt) {
        const h = finiteStep(dt);
        if (h <= 0)
            return;
        const angle = radians(state.loadAngle);
        const acceleration = { x: Math.sin(angle) * state.load, y: -Math.cos(angle) * state.load };
        const oldPositions = nodes.map((node) => ({ ...node.p }));
        for (const node of nodes) {
            if (node.pinned) {
                node.p = { ...node.rest };
                node.v = { x: 0, y: 0 };
            }
            else if (node.id === draggedNode && dragTarget) {
                node.p = { ...dragTarget };
                node.v = { x: 0, y: 0 };
            }
            else {
                node.v = add(node.v, scale(acceleration, h));
                node.v = scale(node.v, Math.exp(-state.damping * h));
                node.v = clampMagnitude(node.v, 4);
                node.p = add(node.p, scale(node.v, h));
            }
            node.stress = 0;
        }
        bars.forEach((bar) => { bar.lambda = 0; });
        const compliance = state.flexibility ** 3 * 0.0015;
        const alpha = compliance / Math.max(EPSILON, h * h);
        for (let iteration = 0; iteration < 10; iteration += 1) {
            for (const bar of bars) {
                const left = nodes[bar.a];
                const right = nodes[bar.b];
                const delta = sub(right.p, left.p);
                const currentLength = Math.max(EPSILON, length(delta));
                const direction = scale(delta, 1 / currentLength);
                const error = currentLength - bar.restLength;
                const leftWeight = inverseMass(left);
                const rightWeight = inverseMass(right);
                const denominator = leftWeight + rightWeight + alpha;
                if (denominator <= EPSILON)
                    continue;
                const deltaLambda = (-error - alpha * bar.lambda) / denominator;
                bar.lambda += deltaLambda;
                left.p = add(left.p, scale(direction, -leftWeight * deltaLambda));
                right.p = add(right.p, scale(direction, rightWeight * deltaLambda));
            }
            for (const node of nodes) {
                if (node.pinned)
                    node.p = { ...node.rest };
                else if (node.id === draggedNode && dragTarget)
                    node.p = { ...dragTarget };
            }
        }
        maxError = 0;
        peakForce = 0;
        for (const bar of bars) {
            const currentLength = distance(nodes[bar.a].p, nodes[bar.b].p);
            bar.error = (currentLength - bar.restLength) / Math.max(EPSILON, bar.restLength);
            const force = Math.abs(bar.lambda) / Math.max(EPSILON, h * h);
            peakForce = Math.max(peakForce, force);
            maxError = Math.max(maxError, Math.abs(bar.error));
            const stress = clamp(force / Math.max(0.2, state.load * 4));
            nodes[bar.a].stress = Math.max(nodes[bar.a].stress, stress);
            nodes[bar.b].stress = Math.max(nodes[bar.b].stress, stress);
        }
        for (const node of nodes) {
            if (node.pinned || node.id === draggedNode) {
                node.v = { x: 0, y: 0 };
            }
            else {
                node.v = clampMagnitude(scale(sub(node.p, oldPositions[node.id]), 1 / h), 4);
            }
            if (!Number.isFinite(node.p.x + node.p.y + node.v.x + node.v.y)) {
                resetDynamics();
                return;
            }
        }
    }
    function currentAreaRatio() {
        return polygonArea(outline.map((id) => nodes[id].p)) / restArea;
    }
    function draw(painter) {
        bars.forEach((bar) => {
            painter.line(nodes[bar.a].rest, nodes[bar.b].rest, {
                color: PHYSICS_COLORS.lineSoft,
                width: 1,
                dash: [4, 5],
            });
        });
        bars.forEach((bar) => {
            const intensity = clamp(Math.abs(bar.error) * 120 + Math.abs(bar.lambda) * 5);
            const color = bar.error >= 0 ? PHYSICS_COLORS.coral : PHYSICS_COLORS.blue;
            painter.line(nodes[bar.a].p, nodes[bar.b].p, {
                color,
                width: 1.4 + 2.3 * intensity,
                alpha: 0.55 + 0.42 * intensity,
            });
        });
        for (const node of nodes) {
            painter.circle(node.p, node.pinned ? 0.031 : 0.025, {
                color: node.pinned ? PHYSICS_COLORS.point : PHYSICS_COLORS.violet,
                fill: node.pinned ? PHYSICS_COLORS.background : PHYSICS_COLORS.violet,
                width: 1.5,
            });
            if (node.pinned) {
                painter.line(add(node.p, { x: -0.045, y: -0.055 }), add(node.p, { x: 0.045, y: -0.055 }), {
                    color: PHYSICS_COLORS.muted,
                    width: 1,
                });
            }
        }
        const angle = radians(state.loadAngle);
        const direction = { x: Math.sin(angle), y: -Math.cos(angle) };
        const start = { x: 0.72, y: 0.63 };
        painter.arrow(start, add(start, scale(direction, 0.22)), {
            color: PHYSICS_COLORS.muted,
            width: 1,
            alpha: 0.85,
            headLength: 0.035,
        });
        painter.text("load", add(start, { x: 0, y: 0.07 }), { color: PHYSICS_COLORS.muted, size: 8 });
    }
    function voices() {
        const jointVoices = nodes.map((node) => normalizedVoice({
            key: `joint-${node.id}`,
            pitch01: clamp((node.p.y + 0.7) / 1.4),
            gain: (node.pinned ? 0.045 : 0.075) + 0.12 * node.stress,
            pan: clamp(node.p.x / 0.82, -1, 1),
            waveform: node.pinned ? "sine" : "triangle",
        }));
        jointVoices.push(normalizedVoice({
            key: "area",
            pitch01: clamp(currentAreaRatio() * 0.72),
            gain: 0.055 + 0.06 * clamp(Math.abs(1 - currentAreaRatio()) * 2),
            pan: 0,
            waveform: "sine",
        }));
        return jointVoices;
    }
    function metrics() {
        return [
            ["Frame", definition().mechanism],
            ["Area", `${Math.round(currentAreaRatio() * 100)}%`],
            ["Bar error", `${(maxError * 100).toFixed(2)}%`],
            ["Constraint force", roundTo(peakForce, 2)],
        ];
    }
    function pointerDown(point) {
        let nearest = null;
        for (const node of nodes) {
            if (node.pinned)
                continue;
            const separation = distance(node.p, point);
            if (!nearest || separation < nearest.separation)
                nearest = { id: node.id, separation };
        }
        if (!nearest || nearest.separation > 0.16)
            return;
        draggedNode = nearest.id;
        dragTarget = { x: clamp(point.x, -0.9, 0.9), y: clamp(point.y, -0.72, 0.72) };
        nodes[draggedNode].p = { ...dragTarget };
        nodes[draggedNode].v = { x: 0, y: 0 };
    }
    function pointerMove(point) {
        if (draggedNode < 0)
            return;
        dragTarget = { x: clamp(point.x, -0.9, 0.9), y: clamp(point.y, -0.72, 0.72) };
        nodes[draggedNode].p = { ...dragTarget };
    }
    function pointerUp(point) {
        if (draggedNode < 0)
            return;
        pointerMove(point);
        const node = nodes[draggedNode];
        events.push(transient(`pluck-${node.id}`, clamp((node.p.y + 0.7) / 1.4), 0.32 + 0.42 * node.stress, clamp(node.p.x / 0.82, -1, 1), "triangle", { decaySeconds: 0.22, attackNoise: 0.08 }));
        draggedNode = -1;
        dragTarget = null;
    }
    function primaryAction() {
        nodes.forEach((node) => {
            if (!node.pinned) {
                const direction = node.id % 2 ? -1 : 1;
                node.v.x += direction * (0.55 + 0.08 * node.id);
                node.v.y += 0.08;
            }
        });
        events.push(transient("shake", 0.48, 0.58, 0, "sawtooth", {
            attackSeconds: 0.002,
            decaySeconds: 0.28,
            attackNoise: 0.18,
        }));
    }
    reset();
    return {
        id: "rigidity",
        title: "Rigidity",
        kicker: "Physics · 03 · Bar-and-joint frameworks",
        description: "The same lengths can define a stable structure or leave a hidden way to move.",
        instruction: "Drag a free joint, compare Square with Braced square, and use Shake to excite the frame.",
        lesson: "Triangles remove shear mechanisms. A quadrilateral can change shape without changing bar length until a diagonal brace makes it rigid.",
        color: PHYSICS_COLORS.violet,
        mappings: [["Joint height", "chord pitch"], ["Constraint force", "voice level"], ["Joint position", "stereo"], ["Enclosed area", "bass pitch"]],
        controls,
        state,
        reset,
        setParam,
        step,
        draw,
        voices,
        consumeEvents: () => events.drain(),
        metrics,
        pointerDown,
        pointerMove,
        pointerUp,
        primaryActionLabel: "Shake",
        primaryAction,
    };
}

function createRollingMeasure() {
    const controls = Object.freeze([
        rangeControl("sides", "Sides", 3, 12, 1, ROLLING_DEFAULTS.sides),
        rangeControl("radius", "Radius", 0.25, 0.56, 0.01, ROLLING_DEFAULTS.radius, (v) => Number(v).toFixed(2)),
        rangeControl("slope", "Slope", -25, 35, 1, ROLLING_DEFAULTS.slope, (v) => `${Math.round(v)}°`),
        rangeControl("gravity", "Gravity", 0, 3, 0.01, ROLLING_DEFAULTS.gravity, (v) => Number(v).toFixed(2)),
        rangeControl("drive", "Drive torque", -1.5, 1.5, 0.01, ROLLING_DEFAULTS.drive, (v) => Number(v).toFixed(2)),
        rangeControl("restitution", "Impact retention", 0.35, 1, 0.01, ROLLING_DEFAULTS.restitution, (v) => Number(v).toFixed(2)),
        rangeControl("drag", "Angular drag", 0, 1.5, 0.01, ROLLING_DEFAULTS.drag, (v) => Number(v).toFixed(2)),
    ]);
    const state = { ...ROLLING_DEFAULTS };
    const events = makeEventQueue();
    let phase = 0;
    let omega = 0;
    let pivotX = 0;
    let contactId = 0;
    let impactCount = 0;
    let impactGlow = 0;
    let swipeStart = null;
    let centroidTrail = [];
    let trailClock = 0;
    const beta = () => TAU / Math.round(state.sides);
    const halfSide = () => state.radius * Math.sin(Math.PI / Math.round(state.sides));
    const inradius = () => state.radius * Math.cos(Math.PI / Math.round(state.sides));
    const sideLength = () => 2 * halfSide();
    const centerRelative = (atPhase = phase) => rotate({ x: -halfSide(), y: inradius() }, -atPhase);
    const centerGround = () => add({ x: pivotX, y: 0 }, centerRelative());
    const inertiaCenter = () => state.radius ** 2 * (1 + 2 * Math.cos(Math.PI / Math.round(state.sides)) ** 2) / 6;
    const inertiaPivot = () => inertiaCenter() + state.radius ** 2;
    const lift01 = () => clamp((centerRelative().y - inradius()) / Math.max(1e-6, state.radius - inradius()));
    function bodyVertices() {
        const count = Math.round(state.sides);
        const centerAtRest = { x: -halfSide(), y: inradius() };
        return Array.from({ length: count }, (_, index) => {
            const angle = -Math.PI / 2 + Math.PI / count + index * TAU / count;
            const local = add(centerAtRest, {
                x: Math.cos(angle) * state.radius,
                y: Math.sin(angle) * state.radius,
            });
            return add({ x: pivotX, y: 0 }, rotate(local, -phase));
        });
    }
    function sceneTransform(point, cameraX = centerGround().x) {
        const angle = radians(state.slope);
        const along = { x: Math.cos(angle), y: -Math.sin(angle) };
        const normal = { x: Math.sin(angle), y: Math.cos(angle) };
        return add({ x: 0, y: -0.34 }, add(scale(along, point.x - cameraX), scale(normal, point.y)));
    }
    function resetDynamics() {
        phase = 0;
        omega = 0;
        pivotX = 0;
        contactId = 0;
        impactCount = 0;
        impactGlow = 0;
        swipeStart = null;
        centroidTrail = [centerGround()];
        trailClock = 0;
        events.clear();
    }
    function reset() {
        Object.assign(state, ROLLING_DEFAULTS);
        resetDynamics();
    }
    function setParam(key, value) {
        const next = coerceControl(controls, key, value);
        if (next === undefined)
            return;
        state[key] = next;
        if (key === "sides" || key === "radius")
            resetDynamics();
    }
    function angularAcceleration(atPhase = phase, atOmega = omega) {
        const center = centerRelative(atPhase);
        const slope = radians(state.slope);
        const gravityTorque = state.gravity * (center.x * Math.cos(slope) + center.y * Math.sin(slope));
        return (gravityTorque + state.drive - state.drag * atOmega) / Math.max(1e-6, inertiaPivot());
    }
    function impactRetention() {
        const geometric = (inertiaCenter() + state.radius ** 2 * Math.cos(beta())) / Math.max(1e-6, inertiaPivot());
        return state.restitution * clamp(geometric, 0, 1);
    }
    function registerContact(direction, incomingOmega) {
        const count = Math.round(state.sides);
        if (direction > 0) {
            pivotX += sideLength();
            phase = 0;
            contactId = (contactId + 1) % count;
        }
        else {
            pivotX -= sideLength();
            phase = beta();
            contactId = (contactId - 1 + count) % count;
        }
        const retained = impactRetention();
        omega = Math.sign(incomingOmega) * Math.abs(incomingOmega) * retained;
        const loss = clamp(Math.abs(incomingOmega - omega) * state.radius / 2.2);
        impactGlow = Math.max(impactGlow, 0.25 + 0.75 * loss);
        impactCount += 1;
        events.push(transient(`contact-${contactId}`, count <= 1 ? 0.5 : contactId / (count - 1), 0.25 + 0.68 * loss, direction, "triangle", { decaySeconds: 0.11 + 0.1 * loss, attackNoise: 0.12 * loss }));
    }
    function shiftRestingSupport(direction) {
        const count = Math.round(state.sides);
        if (direction > 0) {
            pivotX += sideLength();
            phase = 0;
            contactId = (contactId + 1) % count;
        }
        else {
            pivotX -= sideLength();
            phase = beta();
            contactId = (contactId - 1 + count) % count;
        }
    }
    function step(dt) {
        let remaining = finiteStep(dt);
        if (remaining <= 0)
            return;
        impactGlow *= Math.exp(-remaining / 0.12);
        let transitions = 0;
        while (remaining > 1e-8 && transitions < 6) {
            const acceleration = angularAcceleration();
            const candidateOmega = clamp(omega + acceleration * remaining, -14, 14);
            const candidatePhase = phase + candidateOmega * remaining;
            // An edge resting on both adjacent vertices can support a restoring torque.
            if (phase <= 1e-8 && omega >= -1e-5 && candidatePhase < 0) {
                omega = 0;
                if (angularAcceleration(beta(), 0) < -1e-7) {
                    shiftRestingSupport(-1);
                    transitions += 1;
                    continue;
                }
                phase = 0;
                break;
            }
            if (phase >= beta() - 1e-8 && omega <= 1e-5 && candidatePhase > beta()) {
                omega = 0;
                if (angularAcceleration(0, 0) > 1e-7) {
                    shiftRestingSupport(1);
                    transitions += 1;
                    continue;
                }
                phase = beta();
                break;
            }
            if (candidatePhase >= 0 && candidatePhase <= beta()) {
                omega = candidateOmega;
                phase = candidatePhase;
                remaining = 0;
                break;
            }
            const direction = candidatePhase > beta() ? 1 : -1;
            const boundary = direction > 0 ? beta() : 0;
            const denominator = candidatePhase - phase;
            const fraction = Math.abs(denominator) > EPSILON
                ? clamp((boundary - phase) / denominator)
                : 1;
            const used = Math.max(1e-7, remaining * fraction);
            omega = clamp(omega + acceleration * used, -14, 14);
            phase = boundary;
            remaining = Math.max(0, remaining - used);
            registerContact(direction, omega);
            transitions += 1;
            if (Math.abs(omega) < 1e-7 && used <= 1e-7)
                break;
        }
        trailClock += finiteStep(dt);
        if (trailClock >= 1 / 60) {
            trailClock = 0;
            centroidTrail.push(centerGround());
            if (centroidTrail.length > 100)
                centroidTrail.shift();
        }
    }
    function draw(painter) {
        const cameraX = centerGround().x;
        const spacing = Math.max(0.12, sideLength());
        const firstTick = Math.floor((cameraX - 2) / spacing) * spacing;
        for (let x = firstTick; x <= cameraX + 2; x += spacing) {
            const base = sceneTransform({ x, y: 0 }, cameraX);
            const tip = sceneTransform({ x, y: -0.035 }, cameraX);
            painter.line(base, tip, { color: PHYSICS_COLORS.line, width: 1 });
        }
        painter.line(sceneTransform({ x: cameraX - 2, y: 0 }, cameraX), sceneTransform({ x: cameraX + 2, y: 0 }, cameraX), {
            color: PHYSICS_COLORS.line,
            width: 1.3,
        });
        if (centroidTrail.length > 1) {
            painter.polyline(centroidTrail.map((point) => sceneTransform(point, cameraX)), {
                color: PHYSICS_COLORS.orange,
                width: 1,
                alpha: 0.28,
            });
        }
        const vertices = bodyVertices().map((point) => sceneTransform(point, cameraX));
        painter.polyline(vertices, {
            close: true,
            color: PHYSICS_COLORS.orange,
            width: 1.8,
            fill: "rgba(255,184,107,0.055)",
        });
        const center = sceneTransform(centerGround(), cameraX);
        const pivot = sceneTransform({ x: pivotX, y: 0 }, cameraX);
        painter.line(center, pivot, { color: PHYSICS_COLORS.line, width: 1, dash: [3, 4] });
        painter.circle(center, 0.018, { color: PHYSICS_COLORS.point, fill: PHYSICS_COLORS.orange, width: 1.2 });
        painter.circle(pivot, 0.017 + 0.012 * impactGlow, {
            color: PHYSICS_COLORS.point,
            fill: PHYSICS_COLORS.background,
            width: 1.4,
        });
        painter.text(String(contactId + 1), add(pivot, { x: 0, y: -0.065 }), { color: PHYSICS_COLORS.muted, size: 8 });
    }
    function voices() {
        const phasePan = clamp(phase / Math.max(EPSILON, beta()) * 2 - 1, -1, 1);
        return [normalizedVoice({
                key: "centroid",
                pitch01: lift01(),
                gain: 0.09 + 0.16 * clamp(Math.abs(omega) / 8),
                pan: phasePan,
                waveform: "sine",
            })];
    }
    function metrics() {
        return [
            ["Contact", `${contactId + 1} / ${Math.round(state.sides)}`],
            ["Lift", `${Math.round(lift01() * 100)}%`],
            ["Angular speed", roundTo(omega)],
            ["Steps", impactCount],
        ];
    }
    function pointerDown(point) {
        swipeStart = { x: point.x, y: point.y };
    }
    function pointerMove(point) {
        if (!swipeStart)
            return;
        omega = clamp(omega + (point.dx ?? 0) * 0.35, -14, 14);
    }
    function pointerUp(point) {
        if (!swipeStart)
            return;
        const displacement = point.x - swipeStart.x;
        omega = clamp(omega + displacement * 4.5, -14, 14);
        swipeStart = null;
    }
    function primaryAction() {
        omega = clamp(omega + 2.8, -14, 14);
        events.push(transient("nudge", lift01(), 0.48, 0, "triangle", {
            attackSeconds: 0.002,
            decaySeconds: 0.2,
            attackNoise: 0.08,
        }));
    }
    reset();
    return {
        id: "rolling-measure",
        title: "Rolling Measure",
        kicker: "Physics · 04 · Polygonal rolling contact",
        description: "A regular polygon measures the ground one pivot and one side at a time.",
        instruction: "Swipe across the stage or use Nudge, then compare how side count changes the rise-and-fall rhythm.",
        lesson: "No-slip motion is a sequence of rotations about contact vertices. The centroid rises between impacts, then kinetic energy is lost when the pivot changes.",
        color: PHYSICS_COLORS.orange,
        mappings: [["Centroid lift", "continuous pitch"], ["Contact vertex", "impact pitch"], ["Impact loss", "accent level"], ["Roll phase", "stereo"]],
        controls,
        state,
        reset,
        setParam,
        step,
        draw,
        voices,
        consumeEvents: () => events.drain(),
        metrics,
        pointerDown,
        pointerMove,
        pointerUp,
        primaryActionLabel: "Nudge",
        primaryAction,
    };
}

function createFallingFormsScene() {
    const controls = [
        rangeControl("count", "forms", 1, 8, 1, 5),
        selectControl("sides", "geometry", [
            { value: "mixed", label: "mixed" },
            { value: 3, label: "triangles" },
            { value: 4, label: "squares" },
            { value: 5, label: "pentagons" },
            { value: 6, label: "hexagons" },
        ], "mixed"),
        rangeControl("gravity", "gravity", 0, 1.5, 0.01, 0.8, (value) => `${value.toFixed(2)} g`),
        rangeControl("restitution", "bounce", 0, 0.9, 0.01, 0.24),
        rangeControl("friction", "friction", 0, 1, 0.01, 0.55),
        rangeControl("angularDrag", "angular drag", 0, 1.5, 0.01, 0.12),
    ];
    const state = Object.fromEntries(controls.map((control) => [control.key, control.value]));
    const queue = makeEventQueue();
    let bodies = [];
    let contacts = [];
    let cooldowns = new Map();
    let grabbed = null;
    let pointerOffset = { x: 0, y: 0 };
    let pointerPrevious = null;
    const scene = {
        id: "falling-forms",
        title: "Falling Forms",
        kicker: "RIGID BODY / IMPULSE / SUPPORT",
        description: "Convex bodies fall, collide, and turn. Every strike reports the impulse geometry actually produced.",
        instruction: "Drag a form and release it to throw. Flat faces settle; corners turn impact into torque.",
        lesson: "Contact impulses act at particular points, so the same fall can become translation, rotation, or stable support depending on a form's geometry.",
        color: FALLING_COLOR,
        mappings: [["Body height", "continuous pitch"], ["Impact impulse", "accent level"], ["Number of sides", "timbre"], ["Contact position", "stereo"]],
        controls,
        state,
        reset() {
            const random = mulberry32(0xf4111a);
            const count = Math.round(clamp(finiteNumber(state.count, 5), 1, 8));
            bodies = Array.from({ length: count }, (_, index) => {
                const chosenSides = state.sides === "mixed" ? 3 + index % 5 : Math.round(finiteNumber(state.sides, 5));
                const radius = 0.105 + random() * 0.025;
                const column = index % 4;
                const row = Math.floor(index / 4);
                return makeRigidBody(index, chosenSides, radius, { x: -0.66 + column * 0.44 + (random() - 0.5) * 0.05, y: 0.14 + row * 0.34 + random() * 0.04 }, { x: (random() - 0.5) * 0.11, y: 0 }, random() * TAU, (random() - 0.5) * 1.3);
            });
            contacts = [];
            cooldowns = new Map();
            grabbed = null;
            pointerPrevious = null;
            queue.clear();
        },
        setParam(key, value) {
            if (!(key in state))
                return;
            state[key] = key === "sides" ? value : finiteNumber(value, state[key]);
            if (key === "count" || key === "sides")
                scene.reset();
        },
        step(dt) {
            const gravity = -1.8 * clamp(state.gravity, 0, 1.5);
            for (const [key, remaining] of cooldowns) {
                if (remaining <= dt)
                    cooldowns.delete(key);
                else
                    cooldowns.set(key, remaining - dt);
            }
            for (const body of bodies) {
                if (body.held)
                    continue;
                body.velocity.y += gravity * dt;
                body.velocity.x = damp(body.velocity.x, 0.035, dt);
                body.velocity.y = damp(body.velocity.y, 0.018, dt);
                body.omega = damp(body.omega, state.angularDrag, dt);
                body.position = add(body.position, scale(body.velocity, dt));
                body.angle = wrap(body.angle + body.omega * dt, TAU);
            }
            const peaks = new Map();
            const remember = (hit) => {
                if (!hit)
                    return;
                const previous = peaks.get(hit.key);
                if (!previous || hit.impulse > previous.impulse)
                    peaks.set(hit.key, hit);
            };
            for (let pass = 0; pass < 5; pass += 1) {
                for (const body of bodies) {
                    for (const wallHit of wallCandidates(body)) {
                        remember(resolveWall(body, wallHit, state.restitution, state.friction));
                    }
                }
                for (let left = 0; left < bodies.length - 1; left += 1) {
                    for (let right = left + 1; right < bodies.length; right += 1) {
                        remember(resolveRigidPair(bodies[left], bodies[right], state.restitution, state.friction));
                    }
                }
            }
            contacts = [...peaks.values()];
            for (const hit of contacts) {
                if (hit.approachSpeed > 0.12 && hit.impulse > 0.0015 && !cooldowns.has(hit.key)) {
                    const body = bodies.find((candidate) => hit.key.endsWith(`:${candidate.id}`)) ?? bodies[0];
                    queue.push(eventSpec(`impact-${hit.key}`, clamp(0.18 + (hit.point.y - FALLING_BOUNDS.floor) * 0.38 + ((body?.sides ?? 4) - 3) * 0.025), clamp(0.12 + Math.sqrt(hit.impulse) * 0.65), hit.point.x, (body?.sides ?? 4) % 2 ? "triangle" : "square", 0.004, 0.18 + clamp(hit.impulse * 0.5, 0, 0.28)));
                    cooldowns.set(hit.key, 0.085);
                }
            }
        },
        draw(painter) {
            painter.line({ x: FALLING_BOUNDS.left, y: FALLING_BOUNDS.floor }, { x: FALLING_BOUNDS.right, y: FALLING_BOUNDS.floor }, { color: FALLING_COLOR, width: 2, alpha: 0.65 });
            painter.line({ x: FALLING_BOUNDS.left, y: FALLING_BOUNDS.floor }, { x: FALLING_BOUNDS.left, y: FALLING_BOUNDS.ceiling }, { alpha: 0.22 });
            painter.line({ x: FALLING_BOUNDS.right, y: FALLING_BOUNDS.floor }, { x: FALLING_BOUNDS.right, y: FALLING_BOUNDS.ceiling }, { alpha: 0.22 });
            for (const body of bodies) {
                const vertices = rigidVertices(body);
                painter.polyline(vertices, {
                    close: true,
                    color: body.held ? PHYSICS_COLORS.point : FALLING_COLOR,
                    width: body.held ? 2.3 : 1.45,
                    fill: body.held ? "rgba(255,243,214,0.10)" : "rgba(255,130,111,0.065)",
                });
                painter.line(add(body.position, { x: -0.018, y: 0 }), add(body.position, { x: 0.018, y: 0 }), { alpha: 0.35 });
                painter.line(add(body.position, { x: 0, y: -0.018 }), add(body.position, { x: 0, y: 0.018 }), { alpha: 0.35 });
            }
            for (const hit of contacts) {
                painter.circle(hit.point, 0.009 + clamp(hit.impulse * 0.1, 0, 0.02), {
                    color: PHYSICS_COLORS.point,
                    fill: PHYSICS_COLORS.point,
                    width: 0,
                    alpha: 0.45,
                });
                painter.line(hit.point, add(hit.point, scale(hit.normal, 0.05)), { color: FALLING_COLOR, alpha: 0.4 });
            }
        },
        voices() {
            return bodies.map((body) => normalizedVoice({
                key: `body-${body.id}`,
                pitch01: clamp((body.position.y - FALLING_BOUNDS.floor) / (FALLING_BOUNDS.ceiling - FALLING_BOUNDS.floor)),
                gain: clamp(0.012 + length(body.velocity) * 0.025 + Math.abs(body.omega) * 0.009, 0, 0.13),
                pan: body.position.x,
                waveform: body.sides % 2 ? "sine" : "triangle",
            }));
        },
        consumeEvents() { return queue.drain(); },
        metrics() {
            const kinetic = bodies.reduce((sum, body) => sum
                + 0.5 * body.mass * lengthSquared(body.velocity)
                + 0.5 * body.inertia * body.omega * body.omega, 0);
            return {
                forms: bodies.length,
                contacts: contacts.length,
                energy: kinetic.toFixed(3),
            };
        },
        pointerDown(point) {
            const candidates = bodies
                .filter((body) => pointInPolygon(point, rigidVertices(body)) || distance(point, body.position) < body.radius * 1.15)
                .sort((a, b) => distance(point, a.position) - distance(point, b.position));
            grabbed = candidates[0] ?? null;
            if (!grabbed)
                return false;
            grabbed.held = true;
            pointerOffset = sub(grabbed.position, point);
            pointerPrevious = { ...point };
            return true;
        },
        pointerMove(point) {
            if (!grabbed)
                return false;
            const target = add(point, pointerOffset);
            const delta = sub(target, grabbed.position);
            grabbed.velocity = add(scale(grabbed.velocity, 0.35), scale(delta, 38));
            grabbed.position = target;
            grabbed.omega = damp(grabbed.omega, 8, 1 / 60);
            pointerPrevious = { ...point };
            return true;
        },
        pointerUp(point) {
            if (!grabbed)
                return false;
            if (point && pointerPrevious) {
                const delta = sub(point, pointerPrevious);
                grabbed.velocity = add(grabbed.velocity, scale(delta, 20));
            }
            grabbed.held = false;
            grabbed = null;
            pointerPrevious = null;
            return true;
        },
        primaryActionLabel: "Drop again",
        primaryAction() { scene.reset(); },
    };
    scene.reset();
    return scene;
}

function createChargeGardenScene() {
    const controls = [
        selectControl("arrangement", "arrangement", [
            { value: "dipole", label: "dipole" },
            { value: "quadrupole", label: "quadrupole" },
            { value: "ring", label: "alternating ring" },
            { value: "random", label: "seeded scatter" },
        ], "quadrupole"),
        rangeControl("sources", "source charges", 2, 8, 1, 4),
        selectControl("tracerCharge", "test charge", [
            { value: 1, label: "positive" },
            { value: -1, label: "negative" },
        ], 1),
        rangeControl("strength", "field strength", 0.1, 1.5, 0.01, 0.62),
        rangeControl("softening", "source radius", 0.035, 0.16, 0.005, 0.075),
        rangeControl("damping", "drag", 0, 2, 0.01, 0.34),
    ];
    const state = Object.fromEntries(controls.map((control) => [control.key, control.value]));
    const queue = makeEventQueue();
    let sources = [];
    let tracers = [];
    let contourSegments = [];
    let fieldDirty = true;
    let draggedSource = null;
    let pointerStart = null;
    let elapsed = 0;
    function arrangeSources() {
        const random = mulberry32(0xc4a263);
        const count = Math.round(clamp(finiteNumber(state.sources, 4), 2, 8));
        const arrangement = state.arrangement;
        sources = Array.from({ length: count }, (_, index) => {
            let position;
            if (arrangement === "quadrupole") {
                const corners = [
                    { x: -0.46, y: 0.38 }, { x: 0.46, y: 0.38 },
                    { x: 0.46, y: -0.38 }, { x: -0.46, y: -0.38 },
                ];
                const ring = Math.floor(index / 4);
                position = scale(corners[index % 4], 1 - ring * 0.45);
            }
            else if (arrangement === "ring") {
                const angle = index / count * TAU - Math.PI / 2;
                position = { x: Math.cos(angle) * 0.55, y: Math.sin(angle) * 0.48 };
            }
            else if (arrangement === "random") {
                position = { x: lerp(-0.72, 0.72, random()), y: lerp(-0.52, 0.52, random()) };
            }
            else {
                const side = index % 2 === 0 ? -1 : 1;
                const row = Math.floor(index / 2);
                position = { x: side * (0.33 + row * 0.1), y: (row - (count - 2) / 4) * 0.3 };
            }
            const charge = arrangement === "quadrupole"
                ? (index % 4 === 0 || index % 4 === 2 ? 1 : -1)
                : (index % 2 === 0 ? 1 : -1);
            return { id: index, position, charge };
        });
        fieldDirty = true;
    }
    function resetTracers() {
        const random = mulberry32(0x7aace2);
        tracers = Array.from({ length: 3 }, (_, index) => ({
            id: index,
            position: { x: lerp(-0.18, 0.18, random()), y: 0.62 - index * 0.12 },
            velocity: { x: (random() - 0.5) * 0.15, y: -0.05 - random() * 0.08 },
            band: null,
            trail: [],
            lastPotential: 0,
            lastField: 0,
        }));
    }
    const scene = {
        id: "charge-garden",
        title: "Charge Garden",
        kicker: "POTENTIAL / GRADIENT / SUPERPOSITION",
        description: "Positive and negative points bend a potential landscape; tracers make its slope audible.",
        instruction: "Drag a source to redraw every equipotential. Tap open space to plant another alternating charge.",
        lesson: "Potentials add as scalars; their gradient makes a vector field perpendicular to every equipotential contour, including around saddle points.",
        color: CHARGE_COLOR,
        mappings: [["Potential", "pitch"], ["Field magnitude", "voice level"], ["Equipotential crossing", "accent"], ["Tracer position", "stereo"]],
        controls,
        state,
        reset() {
            arrangeSources();
            resetTracers();
            contourSegments = [];
            draggedSource = null;
            pointerStart = null;
            elapsed = 0;
            queue.clear();
        },
        setParam(key, value) {
            if (!(key in state))
                return;
            state[key] = ["arrangement"].includes(key) ? value : finiteNumber(value, state[key]);
            if (key === "arrangement" || key === "sources")
                scene.reset();
            else if (key === "softening")
                fieldDirty = true;
        },
        step(dt) {
            elapsed += dt;
            const tracerSign = finiteNumber(state.tracerCharge, 1) < 0 ? -1 : 1;
            for (const tracer of tracers) {
                const sample = chargeFieldAt(tracer.position, sources, state.softening);
                let acceleration = scale(sample.field, tracerSign * state.strength * 0.13);
                const magnitude = length(acceleration);
                if (magnitude > 7)
                    acceleration = scale(acceleration, 7 / magnitude);
                tracer.velocity = add(tracer.velocity, scale(acceleration, dt));
                tracer.velocity = scale(tracer.velocity, Math.exp(-state.damping * dt));
                tracer.position = add(tracer.position, scale(tracer.velocity, dt));
                if (tracer.position.x < CHARGE_BOUNDS.left || tracer.position.x > CHARGE_BOUNDS.right) {
                    tracer.position.x = clamp(tracer.position.x, CHARGE_BOUNDS.left, CHARGE_BOUNDS.right);
                    tracer.velocity.x *= -0.72;
                }
                if (tracer.position.y < CHARGE_BOUNDS.bottom || tracer.position.y > CHARGE_BOUNDS.top) {
                    tracer.position.y = clamp(tracer.position.y, CHARGE_BOUNDS.bottom, CHARGE_BOUNDS.top);
                    tracer.velocity.y *= -0.72;
                }
                for (const source of sources) {
                    const delta = sub(tracer.position, source.position);
                    const minimumDistance = state.softening * 0.82;
                    if (lengthSquared(delta) < minimumDistance * minimumDistance) {
                        const normal = normalize(delta, { x: tracer.id % 2 ? 1 : -1, y: 0 });
                        tracer.position = add(source.position, scale(normal, minimumDistance));
                        const normalSpeed = dot(tracer.velocity, normal);
                        if (normalSpeed < 0)
                            tracer.velocity = sub(tracer.velocity, scale(normal, 1.65 * normalSpeed));
                    }
                }
                const after = chargeFieldAt(tracer.position, sources, state.softening);
                tracer.lastPotential = after.potential;
                tracer.lastField = length(after.field);
                const normalizedPotential = 0.5 + Math.atan(after.potential / 4) / Math.PI;
                const band = Math.floor(clamp(normalizedPotential) * 9);
                if (tracer.band !== null && band !== tracer.band && length(tracer.velocity) > 0.035) {
                    queue.push(eventSpec(`equipotential-${tracer.id}-${band}-${Math.floor(elapsed * 20)}`, band / 8, 0.12 + clamp(length(tracer.velocity) * 0.2, 0, 0.3), tracer.position.x, "triangle", 0.004, 0.13));
                }
                tracer.band = band;
                tracer.trail.push({ ...tracer.position });
                if (tracer.trail.length > 100)
                    tracer.trail.shift();
            }
        },
        draw(painter) {
            if (fieldDirty) {
                contourSegments = marchPotentialContours(sources, state.softening);
                fieldDirty = false;
            }
            for (const segment of contourSegments) {
                const color = segment.level > 0 ? CHARGE_COLOR : segment.level < 0 ? PHYSICS_COLORS.blue : PHYSICS_COLORS.point;
                painter.line(segment.a, segment.b, { color, width: segment.level === 0 ? 1.25 : 0.7, alpha: segment.level === 0 ? 0.35 : 0.16 });
            }
            for (let row = 0; row < 8; row += 1) {
                for (let column = 0; column < 12; column += 1) {
                    const point = {
                        x: lerp(-0.9, 0.9, column / 11),
                        y: lerp(-0.67, 0.67, row / 7),
                    };
                    const field = chargeFieldAt(point, sources, state.softening).field;
                    const magnitude = length(field);
                    const direction = normalize(field);
                    const extent = 0.022 + 0.047 * Math.tanh(magnitude * 0.12);
                    painter.arrow(point, add(point, scale(direction, extent)), {
                        color: PHYSICS_COLORS.muted,
                        width: 0.7,
                        alpha: 0.16 + 0.2 * Math.tanh(magnitude * 0.08),
                        headLength: 0.015,
                    });
                }
            }
            for (const tracer of tracers) {
                painter.polyline(tracer.trail, { color: PHYSICS_COLORS.point, width: 1, alpha: 0.2 });
                painter.circle(tracer.position, 0.018, { color: PHYSICS_COLORS.point, fill: PHYSICS_COLORS.point, width: 0, alpha: 0.9 });
                const direction = normalize(chargeFieldAt(tracer.position, sources, state.softening).field);
                painter.arrow(tracer.position, add(tracer.position, scale(direction, 0.075)), { color: PHYSICS_COLORS.point, alpha: 0.42, headLength: 0.022 });
            }
            for (const source of sources) {
                const positive = source.charge > 0;
                painter.circle(source.position, state.softening * 0.62, {
                    color: positive ? CHARGE_COLOR : PHYSICS_COLORS.blue,
                    fill: positive ? "rgba(238,111,169,0.14)" : "rgba(125,180,255,0.14)",
                    width: draggedSource === source ? 2.4 : 1.5,
                });
                painter.text(positive ? "+" : "−", source.position, {
                    color: positive ? CHARGE_COLOR : PHYSICS_COLORS.blue,
                    size: 12,
                });
            }
        },
        voices() {
            return tracers.map((tracer) => normalizedVoice({
                key: `tracer-${tracer.id}`,
                pitch01: 0.5 + Math.atan(tracer.lastPotential / 4) / Math.PI,
                gain: 0.025 + 0.11 * Math.tanh(tracer.lastField * 0.045) + 0.04 * Math.tanh(length(tracer.velocity)),
                pan: tracer.position.x,
                waveform: tracer.lastPotential >= 0 ? "sine" : "triangle",
            }));
        },
        consumeEvents() { return queue.drain(); },
        metrics() {
            const focus = tracers[0] ?? { lastPotential: 0, lastField: 0 };
            return {
                potential: focus.lastPotential.toFixed(2),
                field: focus.lastField.toFixed(2),
                sources: sources.length,
            };
        },
        pointerDown(point) {
            pointerStart = { ...point };
            draggedSource = sources
                .filter((source) => distance(source.position, point) < Math.max(0.09, state.softening))
                .sort((a, b) => distance(a.position, point) - distance(b.position, point))[0] ?? null;
            return Boolean(draggedSource);
        },
        pointerMove(point) {
            if (!draggedSource)
                return false;
            draggedSource.position = {
                x: clamp(point.x, CHARGE_BOUNDS.left + 0.04, CHARGE_BOUNDS.right - 0.04),
                y: clamp(point.y, CHARGE_BOUNDS.bottom + 0.04, CHARGE_BOUNDS.top - 0.04),
            };
            fieldDirty = true;
            return true;
        },
        pointerUp(point) {
            if (draggedSource) {
                draggedSource = null;
                pointerStart = null;
                return true;
            }
            if (pointerStart && point && distance(pointerStart, point) < 0.025 && sources.length < 8) {
                const id = Math.max(-1, ...sources.map((source) => source.id)) + 1;
                sources.push({ id, position: { ...point }, charge: sources.length % 2 === 0 ? 1 : -1 });
                state.sources = sources.length;
                fieldDirty = true;
                pointerStart = null;
                return true;
            }
            pointerStart = null;
            return false;
        },
        primaryActionLabel: "Replant",
        primaryAction() { scene.reset(); },
    };
    scene.reset();
    return scene;
}

function createPackingPressureScene() {
    const controls = [
        rangeControl("grains", "grains", 12, 72, 1, 44),
        rangeControl("spread", "size spread", 0, 0.42, 0.01, 0.2),
        rangeControl("gravity", "gravity", 0, 1.5, 0.01, 0.82),
        rangeControl("friction", "friction", 0, 1, 0.01, 0.5),
        rangeControl("compression", "compression", 0, 0.82, 0.01, 0.14),
        rangeControl("agitation", "agitation", 0, 1, 0.01, 0.04),
    ];
    const state = Object.fromEntries(controls.map((control) => [control.key, control.value]));
    const queue = makeEventQueue();
    let grains = [];
    let contacts = [];
    let previousContactKeys = new Set();
    let grabbed = null;
    let draggingRoof = false;
    let pointerPrevious = null;
    let elapsed = 0;
    let pressure = 0;
    let jammed = false;
    const roofY = () => lerp(0.78, -0.12, clamp(state.compression, 0, 0.82) / 0.82);
    function buildPairs() {
        const maximumRadius = Math.max(0.04, ...grains.map((grain) => grain.radius));
        const cellSize = maximumRadius * 2.05;
        const buckets = new Map();
        const cellOf = (grain) => ({
            x: Math.floor((grain.position.x - PACKING_BOUNDS.left) / cellSize),
            y: Math.floor((grain.position.y - PACKING_BOUNDS.floor) / cellSize),
        });
        grains.forEach((grain, index) => {
            const cell = cellOf(grain);
            const key = `${cell.x},${cell.y}`;
            if (!buckets.has(key))
                buckets.set(key, []);
            buckets.get(key).push(index);
        });
        const pairs = [];
        grains.forEach((grain, left) => {
            const cell = cellOf(grain);
            for (let y = cell.y - 1; y <= cell.y + 1; y += 1) {
                for (let x = cell.x - 1; x <= cell.x + 1; x += 1) {
                    for (const right of buckets.get(`${x},${y}`) ?? []) {
                        if (right > left)
                            pairs.push([left, right]);
                    }
                }
            }
        });
        return pairs;
    }
    const scene = {
        id: "packing-pressure",
        title: "Packing Pressure",
        kicker: "PACKING / FORCE CHAINS / JAMMING",
        description: "Disks settle into a contact network. Compression turns overlap constraints into visible force chains.",
        instruction: "Pull the roof downward or stir a grain. Thick links carry the greatest constraint force.",
        lesson: "Local non-overlap constraints organize into system-spanning force chains; pressure, coordination, and diminishing motion mark the onset of jamming.",
        color: PACKING_COLOR,
        mappings: [["Contact height", "pitch"], ["Constraint force", "voice level"], ["New contact", "accent"], ["Packing fraction", "bass pitch"]],
        controls,
        state,
        reset() {
            const random = mulberry32(0x9ac41e);
            const count = Math.round(clamp(finiteNumber(state.grains, 44), 12, 72));
            const baseRadius = clamp(0.073 * Math.sqrt(44 / count), 0.052, 0.095);
            const columns = Math.max(4, Math.floor((PACKING_BOUNDS.right - PACKING_BOUNDS.left) / (baseRadius * 2.15)));
            grains = Array.from({ length: count }, (_, index) => {
                const row = Math.floor(index / columns);
                const column = index % columns;
                const radius = baseRadius * (1 + (random() - 0.5) * 2 * state.spread);
                return {
                    id: index,
                    radius,
                    position: {
                        x: PACKING_BOUNDS.left + baseRadius * 1.3 + column * baseRadius * 2.08 + (row % 2) * baseRadius * 0.72,
                        y: PACKING_BOUNDS.floor + baseRadius * 1.35 + row * baseRadius * 2.05,
                    },
                    velocity: { x: (random() - 0.5) * 0.08, y: random() * 0.03 },
                    held: false,
                    coordination: 0,
                };
            });
            contacts = [];
            previousContactKeys = new Set();
            grabbed = null;
            draggingRoof = false;
            pointerPrevious = null;
            pressure = 0;
            elapsed = 0;
            jammed = false;
            queue.clear();
        },
        setParam(key, value) {
            if (!(key in state))
                return;
            state[key] = finiteNumber(value, state[key]);
            if (key === "grains" || key === "spread")
                scene.reset();
        },
        step(dt) {
            elapsed += dt;
            const previousPositions = new Map();
            for (const grain of grains) {
                previousPositions.set(grain.id, { ...grain.position });
                grain.coordination = 0;
                if (grain.held)
                    continue;
                grain.velocity.x += Math.sin(elapsed * 17 + grain.id * 2.399) * state.agitation * 1.5 * dt;
                grain.velocity.y -= state.gravity * 1.55 * dt;
                grain.velocity = scale(grain.velocity, Math.exp(-0.035 * dt));
                grain.position = add(grain.position, scale(grain.velocity, dt));
            }
            const forceMap = new Map();
            let roofCorrection = 0;
            for (let iteration = 0; iteration < 6; iteration += 1) {
                const roof = roofY();
                for (const grain of grains) {
                    if (grain.held)
                        continue;
                    const leftPenetration = PACKING_BOUNDS.left + grain.radius - grain.position.x;
                    const rightPenetration = grain.position.x + grain.radius - PACKING_BOUNDS.right;
                    const floorPenetration = PACKING_BOUNDS.floor + grain.radius - grain.position.y;
                    const roofPenetration = grain.position.y + grain.radius - roof;
                    if (leftPenetration > 0)
                        grain.position.x += leftPenetration;
                    if (rightPenetration > 0)
                        grain.position.x -= rightPenetration;
                    if (floorPenetration > 0)
                        grain.position.y += floorPenetration;
                    if (roofPenetration > 0) {
                        grain.position.y -= roofPenetration;
                        roofCorrection += roofPenetration;
                        const key = `roof:${grain.id}`;
                        const old = forceMap.get(key);
                        forceMap.set(key, {
                            key,
                            a: grain,
                            b: null,
                            point: { x: grain.position.x, y: roof },
                            correction: (old?.correction ?? 0) + roofPenetration,
                        });
                    }
                }
                for (const [leftIndex, rightIndex] of buildPairs()) {
                    const left = grains[leftIndex];
                    const right = grains[rightIndex];
                    const delta = sub(right.position, left.position);
                    const minimum = left.radius + right.radius;
                    const currentDistance = length(delta);
                    const overlap = minimum - currentDistance;
                    if (overlap <= 0)
                        continue;
                    const fallbackAngle = ((left.id * 97 + right.id * 31) % 360) / 360 * TAU;
                    const normal = normalize(delta, { x: Math.cos(fallbackAngle), y: Math.sin(fallbackAngle) });
                    const leftWeight = left.held ? 0 : 1;
                    const rightWeight = right.held ? 0 : 1;
                    const totalWeight = leftWeight + rightWeight;
                    if (totalWeight <= 0)
                        continue;
                    if (!left.held)
                        left.position = add(left.position, scale(normal, -overlap * leftWeight / totalWeight));
                    if (!right.held)
                        right.position = add(right.position, scale(normal, overlap * rightWeight / totalWeight));
                    const key = left.id < right.id ? `${left.id}:${right.id}` : `${right.id}:${left.id}`;
                    const old = forceMap.get(key);
                    forceMap.set(key, {
                        key,
                        a: left,
                        b: right,
                        point: scale(add(left.position, right.position), 0.5),
                        correction: (old?.correction ?? 0) + overlap,
                    });
                }
            }
            contacts = [...forceMap.values()];
            for (const contact of contacts) {
                contact.force = contact.correction / Math.max(1e-9, dt * dt);
                contact.a.coordination += 1;
                if (contact.b)
                    contact.b.coordination += 1;
            }
            for (const grain of grains) {
                if (grain.held)
                    continue;
                const old = previousPositions.get(grain.id);
                const inferred = scale(sub(grain.position, old), 1 / dt);
                const contactDamping = Math.exp(-state.friction * grain.coordination * dt * 1.7);
                grain.velocity = {
                    x: clamp(inferred.x * contactDamping, -3.5, 3.5),
                    y: clamp(inferred.y, -3.5, 3.5),
                };
            }
            pressure += (roofCorrection / Math.max(1e-9, dt * dt) - pressure) * (1 - Math.exp(-4 * dt));
            const newKeys = new Set(contacts.map((contact) => contact.key));
            for (const contact of contacts) {
                if (!previousContactKeys.has(contact.key) && contact.correction > 0.0002) {
                    const radius = contact.b ? Math.min(contact.a.radius, contact.b.radius) : contact.a.radius;
                    queue.push(eventSpec(`grain-contact-${contact.key}-${Math.floor(elapsed * 40)}`, clamp(0.78 - radius * 4.5 + (contact.point.y - PACKING_BOUNDS.floor) * 0.12), clamp(0.06 + Math.sqrt(contact.correction) * 1.8), contact.point.x, "triangle", 0.003, 0.1));
                }
            }
            previousContactKeys = newKeys;
            const meanCoordination = grains.reduce((sum, grain) => sum + grain.coordination, 0) / Math.max(1, grains.length);
            const kinetic = grains.reduce((sum, grain) => sum + lengthSquared(grain.velocity), 0) / Math.max(1, grains.length);
            jammed = meanCoordination > 2.5 && pressure > 15 && kinetic < 0.02;
        },
        draw(painter) {
            const roof = roofY();
            painter.line({ x: PACKING_BOUNDS.left, y: PACKING_BOUNDS.floor }, { x: PACKING_BOUNDS.left, y: roof }, { alpha: 0.4 });
            painter.line({ x: PACKING_BOUNDS.right, y: PACKING_BOUNDS.floor }, { x: PACKING_BOUNDS.right, y: roof }, { alpha: 0.4 });
            painter.line({ x: PACKING_BOUNDS.left, y: PACKING_BOUNDS.floor }, { x: PACKING_BOUNDS.right, y: PACKING_BOUNDS.floor }, { color: PACKING_COLOR, width: 1.8, alpha: 0.55 });
            painter.line({ x: PACKING_BOUNDS.left, y: roof }, { x: PACKING_BOUNDS.right, y: roof }, { color: PACKING_COLOR, width: draggingRoof ? 3 : 2, alpha: 0.75 });
            const maximumForce = Math.max(1, ...contacts.map((contact) => contact.force));
            for (const contact of contacts) {
                if (!contact.b)
                    continue;
                const strength = Math.sqrt(contact.force / maximumForce);
                painter.line(contact.a.position, contact.b.position, {
                    color: PACKING_COLOR,
                    width: 0.6 + strength * 3.2,
                    alpha: 0.08 + strength * 0.5,
                });
            }
            for (const grain of grains) {
                const activity = clamp(grain.coordination / 6);
                painter.circle(grain.position, grain.radius, {
                    color: grain.held ? PHYSICS_COLORS.point : PACKING_COLOR,
                    fill: `rgba(215,230,91,${(0.025 + activity * 0.13).toFixed(3)})`,
                    width: 0.8 + activity * 1.2,
                    alpha: 0.5 + activity * 0.5,
                });
            }
            if (jammed)
                painter.text("JAMMED", { x: 0, y: roof + 0.07 }, { color: PACKING_COLOR, size: 10 });
        },
        voices() {
            const strongest = [...contacts]
                .filter((contact) => contact.b)
                .sort((a, b) => b.force - a.force)
                .slice(0, 8)
                .sort((a, b) => a.key.localeCompare(b.key));
            const availableArea = (PACKING_BOUNDS.right - PACKING_BOUNDS.left) * (roofY() - PACKING_BOUNDS.floor);
            const fraction = grains.reduce((sum, grain) => sum + Math.PI * grain.radius * grain.radius, 0) / Math.max(0.01, availableArea);
            return [
                ...strongest.map((contact) => normalizedVoice({
                    key: `force-${contact.key}`,
                    pitch01: clamp((contact.point.y - PACKING_BOUNDS.floor) / Math.max(0.1, roofY() - PACKING_BOUNDS.floor)),
                    gain: clamp(0.018 + Math.sqrt(contact.force) * 0.004, 0, 0.16),
                    pan: contact.point.x,
                    waveform: "triangle",
                })),
                normalizedVoice({
                    key: "packing-fraction",
                    pitch01: clamp(0.08 + fraction * 0.48),
                    gain: 0.025 + clamp(fraction * 0.04, 0, 0.055),
                    pan: 0,
                    waveform: "sine",
                }),
            ];
        },
        consumeEvents() { return queue.drain(); },
        metrics() {
            const availableArea = (PACKING_BOUNDS.right - PACKING_BOUNDS.left) * (roofY() - PACKING_BOUNDS.floor);
            const occupiedArea = grains.reduce((sum, grain) => sum + Math.PI * grain.radius * grain.radius, 0);
            const coordination = grains.reduce((sum, grain) => sum + grain.coordination, 0) / Math.max(1, grains.length);
            return {
                packing: `${(100 * occupiedArea / Math.max(0.01, availableArea)).toFixed(1)}%`,
                coordination: coordination.toFixed(2),
                pressure: pressure.toFixed(1),
                state: jammed ? "JAMMED" : "FLOWING",
            };
        },
        pointerDown(point) {
            if (Math.abs(point.y - roofY()) < 0.07) {
                draggingRoof = true;
                return true;
            }
            grabbed = grains
                .filter((grain) => distance(grain.position, point) < grain.radius * 1.45)
                .sort((a, b) => distance(a.position, point) - distance(b.position, point))[0] ?? null;
            if (!grabbed)
                return false;
            grabbed.held = true;
            pointerPrevious = { ...point };
            return true;
        },
        pointerMove(point) {
            if (draggingRoof) {
                state.compression = clamp((0.78 - point.y) / 0.9, 0, 0.82);
                return true;
            }
            if (!grabbed)
                return false;
            const target = {
                x: clamp(point.x, PACKING_BOUNDS.left + grabbed.radius, PACKING_BOUNDS.right - grabbed.radius),
                y: clamp(point.y, PACKING_BOUNDS.floor + grabbed.radius, roofY() - grabbed.radius),
            };
            const delta = sub(target, grabbed.position);
            grabbed.position = target;
            grabbed.velocity = add(scale(grabbed.velocity, 0.25), scale(delta, 40));
            pointerPrevious = { ...point };
            return true;
        },
        pointerUp() {
            const handled = Boolean(grabbed || draggingRoof);
            if (grabbed)
                grabbed.held = false;
            grabbed = null;
            draggingRoof = false;
            pointerPrevious = null;
            return handled;
        },
        primaryActionLabel: "Shake",
        primaryAction() {
            for (const grain of grains) {
                grain.velocity.x += Math.sin(grain.id * 2.399 + elapsed * 11) * 0.42;
                grain.velocity.y += 0.16 + Math.cos(grain.id * 1.731) * 0.08;
            }
            queue.push(eventSpec("packing-shake", 0.24, 0.34, 0, "triangle", 0.003, 0.2));
        },
    };
    scene.reset();
    return scene;
}

function createGeodesicDriftScene() {
    const controls = [
        selectControl("surface", "surface", [
            { value: "plane", label: "plane" },
            { value: "cylinder", label: "cylinder" },
            { value: "sphere", label: "sphere" },
            { value: "torus", label: "torus" },
        ], "torus"),
        rangeControl("heading", "launch heading", -180, 180, 1, 24, (value) => `${Math.round(value)}°`),
        rangeControl("startLatitude", "start latitude", -75, 75, 1, 22, (value) => `${Math.round(value)}°`),
        rangeControl("nearby", "nearby offset", 0.2, 8, 0.1, 2.2, (value) => `${value.toFixed(1)}°`),
        rangeControl("speed", "travel speed", 0.08, 1, 0.01, 0.34),
        rangeControl("yaw", "view yaw", -180, 180, 1, 28, (value) => `${Math.round(value)}°`),
        rangeControl("pitch", "view pitch", -80, 80, 1, -18, (value) => `${Math.round(value)}°`),
    ];
    const state = Object.fromEntries(controls.map((control) => [control.key, control.value]));
    const queue = makeEventQueue();
    let walkers = [];
    let trails = [[], []];
    let travel = 0;
    let separation = 0;
    let currentCurvature = 0;
    let lastGridKey = null;
    let draggingView = false;
    let pointerPrevious = null;
    function makeWalker(headingDegrees) {
        const heading = headingDegrees * Math.PI / 180;
        const latitude = state.startLatitude * Math.PI / 180;
        if (state.surface === "plane")
            return { u: -0.76, v: Math.sin(latitude) * 0.55, du: Math.cos(heading), dv: Math.sin(heading) };
        if (state.surface === "cylinder")
            return { s: 0, z: Math.sin(latitude) * 0.72, ds: Math.cos(heading), dz: Math.sin(heading) };
        if (state.surface === "sphere") {
            const p = { x: Math.cos(latitude), y: Math.sin(latitude), z: 0 };
            const east = { x: 0, y: 0, z: 1 };
            const north = { x: -Math.sin(latitude), y: Math.cos(latitude), z: 0 };
            return { p, tangent: normalize3(add3(scale3(east, Math.cos(heading)), scale3(north, Math.sin(heading)))) };
        }
        const v = latitude * 2;
        const metricU = 0.68 + 0.27 * Math.cos(v);
        return { u: 0, v, du: Math.cos(heading) / metricU, dv: Math.sin(heading) / 0.27 };
    }
    function initializeWalkers() {
        walkers = [makeWalker(state.heading), makeWalker(state.heading + state.nearby)];
        trails = [[embedWalker(state.surface, walkers[0])], [embedWalker(state.surface, walkers[1])]];
        travel = 0;
        separation = 0;
        currentCurvature = gaussianCurvature(state.surface, walkers[0]);
        lastGridKey = null;
    }
    function advanceWalker(walker, amount) {
        if (state.surface === "plane") {
            walker.u += walker.du * amount;
            walker.v += walker.dv * amount;
            return walker;
        }
        if (state.surface === "cylinder") {
            walker.s += walker.ds * amount;
            walker.z += walker.dz * amount;
            return walker;
        }
        if (state.surface === "sphere") {
            const cosine = Math.cos(amount / 0.72);
            const sine = Math.sin(amount / 0.72);
            const nextP = add3(scale3(walker.p, cosine), scale3(walker.tangent, sine));
            const nextTangent = add3(scale3(walker.tangent, cosine), scale3(walker.p, -sine));
            walker.p = normalize3(nextP);
            walker.tangent = normalize3(add3(nextTangent, scale3(walker.p, -dot3(nextTangent, walker.p))));
            return walker;
        }
        return torusRk4(walker, amount);
    }
    function gridKey(walker) {
        if (state.surface === "plane")
            return `${Math.floor((walker.u + 1) * 5)}:${Math.floor((walker.v + 1) * 5)}`;
        if (state.surface === "cylinder")
            return `${Math.floor(wrap(walker.s / 0.56, TAU) / TAU * 12)}:${Math.floor((walker.z + 1) * 5)}`;
        if (state.surface === "sphere") {
            const longitude = wrap(Math.atan2(walker.p.z, walker.p.x), TAU);
            const latitude = Math.asin(clamp(walker.p.y, -1, 1));
            return `${Math.floor(longitude / TAU * 12)}:${Math.floor((latitude + Math.PI / 2) / Math.PI * 8)}`;
        }
        return `${Math.floor(wrap(walker.u, TAU) / TAU * 12)}:${Math.floor(wrap(walker.v, TAU) / TAU * 8)}`;
    }
    function project(point) {
        const yaw = state.yaw * Math.PI / 180;
        const pitch = state.pitch * Math.PI / 180;
        const x1 = Math.cos(yaw) * point.x + Math.sin(yaw) * point.z;
        const z1 = -Math.sin(yaw) * point.x + Math.cos(yaw) * point.z;
        const y2 = Math.cos(pitch) * point.y - Math.sin(pitch) * z1;
        const z2 = Math.sin(pitch) * point.y + Math.cos(pitch) * z1;
        const perspective = 3 / Math.max(1.5, 3 - z2);
        return { x: x1 * perspective * 0.86, y: y2 * perspective * 0.86, depth: z2 };
    }
    function surfaceGrid() {
        const lines = [];
        if (state.surface === "plane") {
            for (let index = -5; index <= 5; index += 1) {
                const coordinate = index / 5;
                lines.push([{ x: coordinate * 0.72, y: -0.72, z: 0 }, { x: coordinate * 0.72, y: 0.72, z: 0 }]);
                lines.push([{ x: -0.72, y: coordinate * 0.72, z: 0 }, { x: 0.72, y: coordinate * 0.72, z: 0 }]);
            }
        }
        else if (state.surface === "cylinder") {
            for (let longitude = 0; longitude < 12; longitude += 1) {
                const angle = longitude / 12 * TAU;
                lines.push(Array.from({ length: 17 }, (_, index) => ({
                    x: 0.56 * Math.cos(angle), y: lerp(-0.72, 0.72, index / 16) * 0.78, z: 0.56 * Math.sin(angle),
                })));
            }
            for (let row = 0; row <= 8; row += 1) {
                const y = lerp(-0.72, 0.72, row / 8) * 0.78;
                lines.push(Array.from({ length: 37 }, (_, index) => {
                    const angle = index / 36 * TAU;
                    return { x: 0.56 * Math.cos(angle), y, z: 0.56 * Math.sin(angle) };
                }));
            }
        }
        else if (state.surface === "sphere") {
            for (let longitude = 0; longitude < 12; longitude += 1) {
                const lon = longitude / 12 * TAU;
                lines.push(Array.from({ length: 25 }, (_, index) => {
                    const lat = lerp(-Math.PI / 2, Math.PI / 2, index / 24);
                    return { x: 0.72 * Math.cos(lat) * Math.cos(lon), y: 0.72 * Math.sin(lat), z: 0.72 * Math.cos(lat) * Math.sin(lon) };
                }));
            }
            for (let row = -3; row <= 3; row += 1) {
                const lat = row / 4 * Math.PI / 2;
                lines.push(Array.from({ length: 37 }, (_, index) => {
                    const lon = index / 36 * TAU;
                    return { x: 0.72 * Math.cos(lat) * Math.cos(lon), y: 0.72 * Math.sin(lat), z: 0.72 * Math.cos(lat) * Math.sin(lon) };
                }));
            }
        }
        else {
            for (let uIndex = 0; uIndex < 12; uIndex += 1) {
                const u = uIndex / 12 * TAU;
                lines.push(Array.from({ length: 29 }, (_, index) => embedWalker("torus", { u, v: index / 28 * TAU })));
            }
            for (let vIndex = 0; vIndex < 8; vIndex += 1) {
                const v = vIndex / 8 * TAU;
                lines.push(Array.from({ length: 37 }, (_, index) => embedWalker("torus", { u: index / 36 * TAU, v })));
            }
        }
        return lines;
    }
    const scene = {
        id: "geodesic-drift",
        title: "Geodesic Drift",
        kicker: "GEODESIC / CURVATURE / DIVERGENCE",
        description: "Nearby straightest paths cross curved surfaces; their separation reveals intrinsic curvature.",
        instruction: "Compare the plane and cylinder, then the sphere and torus. Drag to rotate the surface.",
        lesson: "A geodesic is locally straight on its surface. Gaussian curvature determines whether nearby geodesics tend to converge, remain parallel, or diverge.",
        color: GEODESIC_COLOR,
        mappings: [["Gaussian curvature", "pitch"], ["Nearby-path separation", "detuning"], ["Grid crossing", "accent"], ["Projected position", "stereo"]],
        controls,
        state,
        reset() {
            initializeWalkers();
            draggingView = false;
            pointerPrevious = null;
            queue.clear();
        },
        setParam(key, value) {
            if (!(key in state))
                return;
            state[key] = key === "surface" ? value : finiteNumber(value, state[key]);
            if (["surface", "heading", "startLatitude", "nearby"].includes(key))
                initializeWalkers();
        },
        step(dt) {
            const amount = clamp(state.speed, 0.08, 1) * dt;
            walkers = walkers.map((walker) => advanceWalker(walker, amount));
            travel += amount;
            if ((state.surface === "plane" && walkers.some((walker) => Math.abs(walker.u) > 1.02 || Math.abs(walker.v) > 1.02))
                || (state.surface === "cylinder" && walkers.some((walker) => Math.abs(walker.z) > 0.92))) {
                initializeWalkers();
                return;
            }
            const embedded = walkers.map((walker) => embedWalker(state.surface, walker));
            embedded.forEach((point, index) => {
                trails[index].push(point);
                if (trails[index].length > 300)
                    trails[index].shift();
            });
            separation = length3(add3(embedded[0], scale3(embedded[1], -1)));
            currentCurvature = gaussianCurvature(state.surface, walkers[0]);
            const nextGridKey = gridKey(walkers[0]);
            if (lastGridKey !== null && nextGridKey !== lastGridKey) {
                queue.push(eventSpec(`grid-${nextGridKey}-${Math.floor(travel * 20)}`, clamp(0.5 + Math.atan(currentCurvature / 3) / Math.PI), 0.12, project(embedded[0]).x, "triangle", 0.003, 0.1));
            }
            lastGridKey = nextGridKey;
        },
        draw(painter) {
            const grid = surfaceGrid();
            for (const line of grid)
                painter.polyline(line.map(project), { color: GEODESIC_COLOR, width: 0.65, alpha: 0.13 });
            painter.polyline(trails[1].map(project), { color: PHYSICS_COLORS.violet, width: 1.2, alpha: 0.48 });
            painter.polyline(trails[0].map(project), { color: GEODESIC_COLOR, width: 2, alpha: 0.85 });
            const positions = walkers.map((walker) => project(embedWalker(state.surface, walker)));
            painter.circle(positions[1], 0.015, { color: PHYSICS_COLORS.violet, fill: PHYSICS_COLORS.violet, width: 0 });
            painter.circle(positions[0], 0.02, { color: PHYSICS_COLORS.point, fill: PHYSICS_COLORS.point, width: 0 });
            painter.line(positions[0], positions[1], { color: PHYSICS_COLORS.point, width: 0.7, alpha: 0.28, dash: [3, 4] });
        },
        voices() {
            const positions = walkers.map((walker) => project(embedWalker(state.surface, walker)));
            const curvaturePitch = clamp(0.5 + Math.atan(currentCurvature / 3) / Math.PI);
            const spread = clamp(separation / 0.5);
            return [
                normalizedVoice({ key: "geodesic-primary", pitch01: curvaturePitch, gain: 0.11, pan: positions[0].x, waveform: "sine" }),
                normalizedVoice({ key: "geodesic-neighbour", pitch01: clamp(curvaturePitch + 0.055 * spread), gain: 0.07 + 0.035 * spread, pan: positions[1].x, waveform: "sine" }),
            ];
        },
        consumeEvents() { return queue.drain(); },
        metrics() {
            return {
                curvature: `${currentCurvature >= 0 ? "+" : ""}${currentCurvature.toFixed(3)}`,
                separation: separation.toFixed(3),
                distance: travel.toFixed(2),
            };
        },
        pointerDown(point) {
            draggingView = true;
            pointerPrevious = { ...point };
            return true;
        },
        pointerMove(point) {
            if (!draggingView || !pointerPrevious)
                return false;
            const delta = sub(point, pointerPrevious);
            state.yaw = ((state.yaw + delta.x * 120 + 180) % 360 + 360) % 360 - 180;
            state.pitch = clamp(state.pitch + delta.y * 120, -80, 80);
            pointerPrevious = { ...point };
            return true;
        },
        pointerUp() {
            const handled = draggingView;
            draggingView = false;
            pointerPrevious = null;
            return handled;
        },
        primaryActionLabel: "Relaunch",
        primaryAction() {
            initializeWalkers();
            queue.push(eventSpec("geodesic-relaunch", clamp(0.5 + Math.atan(currentCurvature / 3) / Math.PI), 0.3, 0, "sine", 0.004, 0.2));
        },
    };
    scene.reset();
    return scene;
}

function createKineticHullScene() {
    const controls = [
        rangeControl("points", "moving points", 8, 28, 1, 18),
        rangeControl("speed", "point speed", 0.04, 0.8, 0.01, 0.27),
        selectControl("boundary", "boundary", [
            { value: "box", label: "rectangle" },
            { value: "circle", label: "circle" },
        ], "box"),
        selectControl("structure", "structure", [
            { value: "hull", label: "convex hull" },
            { value: "delaunay", label: "Delaunay" },
            { value: "both", label: "both" },
        ], "both"),
        rangeControl("trail", "trail length", 0, 40, 1, 18),
    ];
    const state = Object.fromEntries(controls.map((control) => [control.key, control.value]));
    const queue = makeEventQueue();
    let points = [];
    let hull = [];
    let triangulation = [];
    let previousHullIds = new Set();
    let previousEdgeKeys = new Set();
    let flashes = [];
    let selected = null;
    let pointerPrevious = null;
    let structureClock = 0;
    let lastEdgeChanges = 0;
    let elapsed = 0;
    function updateStructures(emit = true) {
        // The shared computational-geometry helpers operate on top-level x/y
        // records. Keep simulation state in `position`, but hand them lightweight
        // identity-preserving projections and resolve the ids back afterward.
        const byId = new Map(points.map((point) => [point.id, point]));
        const geometryPoints = points.map((point) => ({
            id: point.id,
            x: point.position.x,
            y: point.position.y,
        }));
        const nextHull = convexHull(geometryPoints).map((point) => byId.get(point.id));
        const nextHullIds = new Set(nextHull.map((point) => point.id));
        if (emit) {
            const changed = [...nextHullIds].filter((id) => !previousHullIds.has(id))
                .concat([...previousHullIds].filter((id) => !nextHullIds.has(id)));
            for (const id of changed.slice(0, 4)) {
                const point = points.find((candidate) => candidate.id === id);
                if (!point)
                    continue;
                flashes.push({ kind: "point", id, ttl: 0.28 });
                queue.push(eventSpec(`hull-change-${id}-${Math.floor(elapsed * 30)}`, clamp((point.position.y + 0.78) / 1.56), 0.24, point.position.x, "triangle", 0.004, 0.18));
            }
        }
        hull = nextHull;
        previousHullIds = nextHullIds;
        triangulation = delaunayEdges(geometryPoints).map((edge) => ({
            key: edge.key,
            a: byId.get(edge.a.id),
            b: byId.get(edge.b.id),
        }));
        const nextEdgeKeys = new Set(triangulation.map((edge) => edge.key));
        const added = [...nextEdgeKeys].filter((key) => !previousEdgeKeys.has(key));
        const removed = [...previousEdgeKeys].filter((key) => !nextEdgeKeys.has(key));
        lastEdgeChanges = emit ? added.length + removed.length : 0;
        if (emit) {
            for (const key of added.slice(0, 3)) {
                const edge = triangulation.find((candidate) => candidate.key === key);
                if (!edge)
                    continue;
                flashes.push({ kind: "edge", key, ttl: 0.22 });
                const midpoint = scale(add(edge.a.position, edge.b.position), 0.5);
                queue.push(eventSpec(`edge-change-${key}-${Math.floor(elapsed * 30)}`, clamp(0.78 - distance(edge.a.position, edge.b.position) * 0.42), 0.13, midpoint.x, "square", 0.003, 0.1));
            }
        }
        previousEdgeKeys = nextEdgeKeys;
    }
    const scene = {
        id: "kinetic-hull",
        title: "Kinetic Hull",
        kicker: "CONVEXITY / DELAUNAY / TOPOLOGY",
        description: "Moving points continually renegotiate their convex boundary and nearest-neighbour triangulation.",
        instruction: "Drag a point and release it. Boundary membership and Delaunay edge changes become notes.",
        lesson: "Continuous point motion produces discrete combinatorial events: points enter or leave the convex hull and Delaunay diagonals exchange at critical configurations.",
        color: HULL_COLOR,
        mappings: [["Hull-point height", "pitch"], ["Exterior turn", "voice level"], ["Edge change", "accent"], ["Hull area", "bass pitch"]],
        controls,
        state,
        reset() {
            const random = mulberry32(0x4b11c0);
            const count = Math.round(clamp(finiteNumber(state.points, 18), 8, 28));
            points = [];
            for (let index = 0; index < count; index += 1) {
                let position;
                for (let attempt = 0; attempt < 40; attempt += 1) {
                    const candidate = { x: lerp(-0.82, 0.82, random()), y: lerp(-0.64, 0.64, random()) };
                    if (state.boundary !== "circle" || length(candidate) < 0.78) {
                        position = candidate;
                        break;
                    }
                }
                position ??= { x: 0, y: 0 };
                const angle = random() * TAU;
                points.push({
                    id: index,
                    position,
                    direction: { x: Math.cos(angle), y: Math.sin(angle) },
                    trail: [{ ...position }],
                    held: false,
                });
            }
            hull = [];
            triangulation = [];
            previousHullIds = new Set();
            previousEdgeKeys = new Set();
            flashes = [];
            selected = null;
            pointerPrevious = null;
            structureClock = 0;
            lastEdgeChanges = 0;
            elapsed = 0;
            queue.clear();
            updateStructures(false);
        },
        setParam(key, value) {
            if (!(key in state))
                return;
            state[key] = ["boundary", "structure"].includes(key) ? value : finiteNumber(value, state[key]);
            if (key === "points" || key === "boundary")
                scene.reset();
        },
        step(dt) {
            elapsed += dt;
            for (const point of points) {
                if (point.held)
                    continue;
                point.position = add(point.position, scale(point.direction, state.speed * dt));
                if (state.boundary === "circle") {
                    const radius = 0.82;
                    const magnitude = length(point.position);
                    if (magnitude > radius) {
                        const outward = scale(point.position, 1 / magnitude);
                        point.position = scale(outward, radius);
                        point.direction = normalize(sub(point.direction, scale(outward, 2 * dot(point.direction, outward))));
                    }
                }
                else {
                    if (point.position.x < -0.92 || point.position.x > 0.92) {
                        point.position.x = clamp(point.position.x, -0.92, 0.92);
                        point.direction.x *= -1;
                    }
                    if (point.position.y < -0.72 || point.position.y > 0.72) {
                        point.position.y = clamp(point.position.y, -0.72, 0.72);
                        point.direction.y *= -1;
                    }
                }
                point.trail.push({ ...point.position });
                const trailLength = Math.round(clamp(state.trail, 0, 40));
                while (point.trail.length > Math.max(1, trailLength))
                    point.trail.shift();
            }
            const byId = new Map(points.map((point) => [point.id, point]));
            hull = convexHull(points.map((point) => ({
                id: point.id,
                x: point.position.x,
                y: point.position.y,
            }))).map((point) => byId.get(point.id));
            const nextHullIds = new Set(hull.map((point) => point.id));
            if ([...nextHullIds].some((id) => !previousHullIds.has(id)) || [...previousHullIds].some((id) => !nextHullIds.has(id))) {
                updateStructures(true);
                structureClock = 0;
            }
            else {
                previousHullIds = nextHullIds;
                structureClock += dt;
                if (structureClock >= 1 / 24) {
                    updateStructures(true);
                    structureClock %= 1 / 24;
                }
                else
                    lastEdgeChanges = 0;
            }
            flashes = flashes.map((flash) => ({ ...flash, ttl: flash.ttl - dt })).filter((flash) => flash.ttl > 0);
        },
        draw(painter) {
            if (state.boundary === "circle")
                painter.circle({ x: 0, y: 0 }, 0.82, { color: PHYSICS_COLORS.line, fill: null, width: 1, alpha: 0.5 });
            else
                painter.polyline([
                    { x: -0.92, y: -0.72 }, { x: 0.92, y: -0.72 },
                    { x: 0.92, y: 0.72 }, { x: -0.92, y: 0.72 },
                ], { close: true, color: PHYSICS_COLORS.line, width: 1, alpha: 0.45 });
            if (state.structure === "delaunay" || state.structure === "both") {
                for (const edge of triangulation) {
                    const flash = flashes.find((candidate) => candidate.kind === "edge" && candidate.key === edge.key);
                    painter.line(edge.a.position, edge.b.position, {
                        color: flash ? PHYSICS_COLORS.point : PHYSICS_COLORS.blue,
                        width: flash ? 2 : 0.75,
                        alpha: flash ? clamp(flash.ttl * 4) : 0.2,
                    });
                }
            }
            if ((state.structure === "hull" || state.structure === "both") && hull.length > 2) {
                painter.polyline(hull.map((point) => point.position), {
                    close: true,
                    color: HULL_COLOR,
                    width: 2,
                    alpha: 0.82,
                    fill: "rgba(245,166,91,0.055)",
                });
            }
            for (const point of points) {
                if (state.trail > 1)
                    painter.polyline(point.trail, { color: HULL_COLOR, width: 0.7, alpha: 0.12 });
                const onHull = previousHullIds.has(point.id);
                const flash = flashes.find((candidate) => candidate.kind === "point" && candidate.id === point.id);
                painter.circle(point.position, point.held ? 0.027 : onHull ? 0.021 : 0.014, {
                    color: flash ? PHYSICS_COLORS.point : onHull ? HULL_COLOR : PHYSICS_COLORS.muted,
                    fill: onHull ? "rgba(245,166,91,0.22)" : PHYSICS_COLORS.background,
                    width: point.held ? 2.2 : 1.2,
                    alpha: flash ? 1 : onHull ? 0.95 : 0.6,
                });
            }
        },
        voices() {
            const ranked = hull.map((point, index) => ({
                point,
                turn: exteriorTurn(hull[(index - 1 + hull.length) % hull.length], point, hull[(index + 1) % hull.length]),
            })).sort((a, b) => b.turn - a.turn).slice(0, 10).sort((a, b) => a.point.id - b.point.id);
            const area = hull.length > 2 ? hullArea(hull.map((point) => point.position)) : 0;
            return [
                ...ranked.map(({ point, turn }) => normalizedVoice({
                    key: `hull-${point.id}`,
                    pitch01: clamp((point.position.y + 0.72) / 1.44),
                    gain: clamp(0.025 + turn / Math.PI * 0.16),
                    pan: point.position.x,
                    waveform: "sine",
                })),
                normalizedVoice({ key: "hull-area", pitch01: clamp(0.08 + area * 0.22), gain: 0.025 + clamp(area * 0.015, 0, 0.03), pan: 0, waveform: "triangle" }),
            ];
        },
        consumeEvents() { return queue.drain(); },
        metrics() {
            const positions = hull.map((point) => point.position);
            return {
                hull: `${hull.length}/${points.length}`,
                area: (positions.length > 2 ? hullArea(positions) : 0).toFixed(3),
                perimeter: (positions.length > 2 ? polygonPerimeter(positions) : 0).toFixed(3),
                changes: lastEdgeChanges,
            };
        },
        pointerDown(point) {
            selected = points
                .filter((candidate) => distance(candidate.position, point) < 0.075)
                .sort((a, b) => distance(a.position, point) - distance(b.position, point))[0] ?? null;
            if (selected) {
                selected.held = true;
                pointerPrevious = { ...point };
                return true;
            }
            if (points.length < 28) {
                const id = Math.max(-1, ...points.map((candidate) => candidate.id)) + 1;
                points.push({ id, position: { ...point }, direction: normalize({ x: Math.cos(id * 2.17), y: Math.sin(id * 2.17) }), trail: [{ ...point }], held: false });
                state.points = points.length;
                updateStructures(true);
                return true;
            }
            return false;
        },
        pointerMove(point) {
            if (!selected)
                return false;
            const delta = sub(point, selected.position);
            selected.position = { ...point };
            if (lengthSquared(delta) > 1e-8)
                selected.direction = normalize(add(scale(selected.direction, 0.3), scale(normalize(delta), 0.7)));
            selected.trail.push({ ...point });
            pointerPrevious = { ...point };
            return true;
        },
        pointerUp() {
            if (!selected)
                return false;
            selected.held = false;
            selected = null;
            pointerPrevious = null;
            updateStructures(true);
            return true;
        },
        primaryActionLabel: "Reseed",
        primaryAction() { scene.reset(); },
    };
    scene.reset();
    return scene;
}

