sanitizeAlgorithmicScoreParams({
  ...instrument.defaults,
  seed: 0x51c0ffee,
})

Object.freeze({
  ...CANTOR_LOCK_DEFAULTS,
  level: 0.48,
  tightened: false,
})

Object.freeze({
  1: Object.freeze({ rootMidi: 48, centerA: 0.44, centerB: 0.31, spread: 0.86 }),
  2: Object.freeze({ rootMidi: 43, centerA: 0.28, centerB: 0.56, spread: 0.92 }),
  3: Object.freeze({ rootMidi: 36, centerA: 0.18, centerB: 0.38, spread: 0.78 }),
})

Object.freeze({
  landscapeId: "single-basin",
  durationSeconds: DEFAULT_ANNEAL_DURATION_SECONDS,
  gamma: DEFAULT_TRANSVERSE_FIELD,
  progress: 0,
})

Object.freeze({
  candy: CANDY_DEFAULTS,
  sandy: SANDY_DEFAULTS,
})

Object.freeze({
  minimumFrequency: 70,
  maximumFrequency: 1_200,
  gain: 0.18,
})

Object.freeze({
  ...CHAOTIC_FM_PRESETS[0].settings,
  output: 0.42,
})

Object.freeze({
  ...CHAOTIC_PM_PRESETS[1].settings,
  output: 0.58,
})

Object.freeze({
  tone: Object.freeze({
    strike: 0.04, attackMs: 4, releaseMs: 70, prechargeMs: 0, burst: 0,
    pulseRateHz: 0, pulseDepth: 0, pushPull: 0.08, brightness: 0.34, noise: 0.04,
  }),
  plosive: Object.freeze({
    strike: 0.9, attackMs: 0.8, releaseMs: 42, prechargeMs: 22, burst: 0.94,
